declare global {
  interface Window {
    BarcodeDetector?: {
      new (options?: { formats?: string[] }): {
        detect: (source: CanvasImageSource) => Promise<Array<{ rawValue?: string }>>;
      };
      getSupportedFormats?: () => Promise<string[]>;
    };
    Html5Qrcode?: new (
      elementId: string,
      config?: { verbose?: boolean }
    ) => {
      start: (
        cameraConfig: unknown,
        config: unknown,
        onSuccess: (decodedText: string) => void | Promise<void>,
        onError?: (errorMessage: string) => void
      ) => Promise<void>;
      stop: () => Promise<void>;
      clear: () => Promise<void>;
      isScanning?: boolean;
    };
    jspdf?: {
      jsPDF: new (options?: { orientation?: string; unit?: string; format?: string }) => {
        setFontSize: (size: number) => void;
        setTextColor: (r: number, g?: number, b?: number) => void;
        setFillColor: (r: number, g?: number, b?: number) => void;
        setDrawColor: (r: number, g?: number, b?: number) => void;
        setLineWidth: (width: number) => void;
        addFileToVFS: (filename: string, filecontent: string) => void;
        addFont: (postScriptName: string, fontName: string, fontStyle: string, fontWeight?: string | number) => void;
        setFont: (fontName: string, fontStyle?: string) => void;
        text: (text: string | string[], x: number, y: number, options?: unknown) => void;
        rect: (x: number, y: number, width: number, height: number, style?: string) => void;
        roundedRect: (x: number, y: number, width: number, height: number, rx: number, ry: number, style?: string) => void;
        line: (x1: number, y1: number, x2: number, y2: number) => void;
        addImage: (imageData: string, format: string, x: number, y: number, width: number, height: number) => void;
        splitTextToSize: (text: string, size: number) => string[];
        output: (type: "blob") => Blob;
        setPage: (pageNumber: number) => void;
        autoTable?: (options: unknown) => void;
        lastAutoTable?: { finalY?: number };
        internal?: { getNumberOfPages?: () => number };
      };
    };
    XLSX?: {
      utils: {
        book_new: () => unknown;
        aoa_to_sheet: (rows: Array<Array<string | number>>) => unknown;
        book_append_sheet: (workbook: unknown, worksheet: unknown, name: string) => void;
        sheet_to_json: <T = Record<string, unknown>>(worksheet: unknown, options?: Record<string, unknown>) => T[];
      };
      read: (data: ArrayBuffer, options: { type: string }) => {
        SheetNames: string[];
        Sheets: Record<string, unknown>;
      };
      write: (workbook: unknown, options: { bookType: string; type: string }) => ArrayBuffer;
    };
  }
}

