function createLabelElement(
  id: string,
  type: LabelTemplateElementType,
  patch: Partial<LabelTemplateElementConfig> = {}
): LabelTemplateElementConfig {
  return {
    id,
    type,
    key: "",
    label: "",
    text: "",
    visible: true,
    x: 4,
    y: 4,
    width: 35,
    height: 12,
    zIndex: 10,
    fontFamily: "Arial",
    labelFontSize: 5.2,
    valueFontSize: 8,
    labelBold: true,
    bold: false,
    italic: false,
    underline: false,
    align: "left",
    verticalAlign: "top",
    stackedLabel: false,
    wrap: false,
    maxLines: 2,
    prefix: "",
    suffix: "",
    charSpacing: 0,
    rotation: 0,
    textColor: "#000000",
    fillColor: "#ffffff",
    borderColor: "#000000",
    borderWidth: 0.6,
    borderRadius: 0,
    lineWidth: 0.8,
    hideWhenEmpty: false,
    showHumanReadable: false,
    imageUrl: "",
    imageStoragePath: "",
    imageFit: "contain",
    keepAspectRatio: true,
    imageAspectRatio: 1,
    opacity: 1,
    locked: false,
    ...patch,
  };
}

