  if (fieldId === PRODUCTION_CARD_NYILO_FIELD_ID) return "Nyíló";
  if (fieldId === PRODUCTION_CARD_AJTOLAPOK_FIELD_ID) return "Ajtólapok";
  if (fieldId === PRODUCTION_CARD_TOKLEC_KESZ_FIELD_ID) return "Tokléc";
