function createDefaultProductionCardProfile(stationName = "Munkaállomás"): ProductionMonitorProfile {
  const cleanStationName = String(stationName || "Munkaállomás").trim() || "Munkaállomás";
  const theme = cloneProductionMonitorTheme(PRODUCTION_MONITOR_THEME_PRESETS["industrial-night"].theme);
  const table = createDefaultProductionMonitorTable(`${cleanStationName} termelési kártya`, "card-table-default", theme);
  table.dataSource = "production-plan";
  const usesSzinterExcelSchema = ["szinter", "kezi_szinter"].includes(
    getStationPlanIdentityKey(cleanStationName)
  );
  const allProductionCardFieldIds = [...getProductionCardFieldIdsForTable(table, cleanStationName)];
  const crossStationStatusFieldIds = allProductionCardFieldIds.filter(
    isProductionCardCrossStationStatusField
  );

  table.fieldOrder = usesSzinterExcelSchema
    ? allProductionCardFieldIds
    : [
        ...PRODUCTION_CARD_FIELD_IDS,
        ...crossStationStatusFieldIds,
      ];

  table.hiddenFieldIds = Array.from(new Set([
    ...(usesSzinterExcelSchema ? [] : [PRODUCTION_CARD_DATE_FIELD_ID]),
    PRODUCTION_CARD_AJTOLAPOK_FIELD_ID,
    PRODUCTION_CARD_TOKLEC_KESZ_FIELD_ID,
    PRODUCTION_CARD_KULSO_LAP_KESZ_FIELD_ID,
    PRODUCTION_CARD_BELSO_LAP_KESZ_FIELD_ID,
    PRODUCTION_CARD_LAP_TOKLEC_KESZ_FIELD_ID,
    PRODUCTION_CARD_KISZALLITASI_DATUM_FIELD_ID,
    ...crossStationStatusFieldIds,
  ]));
  table.fieldStyles = {
    [PRODUCTION_CARD_ORDER_FIELD_ID]: {
      ...normalizeProductionMonitorFieldStyle(null),
      widthWeight: 1.35,
      textAlign: "left",
    },
    [PRODUCTION_CARD_PRODUCT_FIELD_ID]: {
      ...normalizeProductionMonitorFieldStyle(null),
      widthWeight: 1.6,
      textAlign: "left",
    },
    [PRODUCTION_CARD_STATUS_FIELD_ID]: {
      ...normalizeProductionMonitorFieldStyle(null),
      widthWeight: 1.05,
    },
    [PRODUCTION_CARD_START_WORKER_FIELD_ID]: {
      ...normalizeProductionMonitorFieldStyle(null),
      widthWeight: 1.3,
      textAlign: "left",
    },
    [PRODUCTION_CARD_END_WORKER_FIELD_ID]: {
      ...normalizeProductionMonitorFieldStyle(null),
      widthWeight: 1.3,
      textAlign: "left",
    },
    [PRODUCTION_CARD_TOK_FIELD_ID]: {
      ...normalizeProductionMonitorFieldStyle(null),
      widthWeight: 0.8,
    },
    [PRODUCTION_CARD_NYILO_FIELD_ID]: {
      ...normalizeProductionMonitorFieldStyle(null),
      widthWeight: 0.8,
    },
  };
  const priorityTable = createDefaultPriorityCardTable(theme, cleanStationName);
  const backlogTable = createDefaultBacklogCardTable(theme, cleanStationName);
  const tables = isScrapReplacementProductionCardStation(cleanStationName)
    ? [priorityTable, createDefaultScrapReplacementCardTable(theme), backlogTable, table]
    : [priorityTable, backlogTable, table];
  return {
    id: `production-card-${cleanStationName}`,
    name: `${cleanStationName} termelési kártya`,
    themePresetId: "industrial-night",
    zoomPercent: 90,
    theme,
    tables,
    activeTableId: table.id,
  };
}

function isLegacyPriorityProductionCardTable(
  table: Pick<ProductionMonitorTableConfig, "id" | "name" | "title" | "dataSource">
): boolean {
  if (table.dataSource === "priority") return true;

  const id = normalizeLooseText(table.id);
  const name = normalizeLooseText(table.name);
  const title = normalizeLooseText(table.title);

  return id === "card-table-priority"
    || name === "prioritasi kartya"
    || title === "prioritasi kartya"
    || name.startsWith("prioritasi kartya ")
    || title.startsWith("prioritasi kartya ");
}

function getStoredProductionCardPriorityProblemState(value: unknown): {
  exactPriorityCount: number;
  legacyPriorityCount: number;
  needsCleanup: boolean;
} {
  const raw = value && typeof value === "object"
    ? value as { tables?: unknown[] }
    : {};

  if (!Array.isArray(raw.tables)) {
    return {
      exactPriorityCount: 0,
      legacyPriorityCount: 0,
      needsCleanup: true,
    };
  }

  let exactPriorityCount = 0;
  let legacyPriorityCount = 0;

  raw.tables.forEach((rawTable) => {
    if (!rawTable || typeof rawTable !== "object") return;

    const table = rawTable as Partial<ProductionMonitorTableConfig>;
    const dataSource = String(table.dataSource || "");

    if (dataSource === "priority") {
      exactPriorityCount += 1;
      return;
    }

    const candidate: Pick<ProductionMonitorTableConfig, "id" | "name" | "title" | "dataSource"> = {
      id: String(table.id || ""),
      name: String(table.name || ""),
      title: String(table.title || ""),
      dataSource: dataSource === "scrap-replacement"
        ? "scrap-replacement"
        : dataSource === "backlog"
          ? "backlog"
          : "production-plan",
    };

    if (isLegacyPriorityProductionCardTable(candidate)) {
      legacyPriorityCount += 1;
    }
  });

  return {
    exactPriorityCount,
    legacyPriorityCount,
    needsCleanup: exactPriorityCount !== 1 || legacyPriorityCount > 0,
  };
}

function normalizeProductionCardProfile(value: unknown, stationName: string): ProductionMonitorProfile {
  if (!value || typeof value !== "object") return createDefaultProductionCardProfile(stationName);
  const normalized = normalizeProductionMonitorProfile(value, 0);
  const scrapReplacementStation = isScrapReplacementProductionCardStation(stationName);
  let tables = normalized.tables.length > 0
    ? normalized.tables.map((table, index) => {
        const dataSource: ProductionCardTableDataSource = isLegacyPriorityProductionCardTable(table)
          ? "priority"
          : table.dataSource === "scrap-replacement"
            ? "scrap-replacement"
            : table.dataSource === "backlog"
              ? "backlog"
              : "production-plan";
        // FONTOS: a production-plan táblák mezői munkaállomásonként dinamikusak.
        // Korábban itt csak a statikus PRODUCTION_CARD_FIELD_IDS lista volt érvényes,
        // ezért a *_terv táblából származó mezők (pl. gyártási szám, rsz, külső lap)
        // hiddenFieldIds / fieldStyles beállításai betöltéskor kieshettek. Emiatt a
        // felhasználó elrejtett egy oszlopot, a mentés sikerült, de újratöltés után
        // az oszlop újra megjelent. A valid mezőlista most ugyanaz a dinamikus lista,
        // amelyet a szerkesztő és a kártya renderelése is használ.
        const tableForFields: ProductionMonitorTableConfig = { ...table, dataSource };
        const validFields: readonly string[] = dataSource === "scrap-replacement"
          ? PRODUCTION_CARD_SCRAP_FIELD_IDS
          : getProductionCardFieldIdsForTable(tableForFields, stationName);
        const validFieldSet = new Set(validFields);
        const nextFieldOrder = Array.from(new Set([
          ...table.fieldOrder.filter((fieldId) => validFieldSet.has(fieldId)),
          ...validFields.filter((fieldId) => !table.fieldOrder.includes(fieldId)),
        ]));
        const newlyAddedOptionalFields = [
          PRODUCTION_CARD_SCRAP_ELAPSED_FIELD_ID,
          PRODUCTION_CARD_BACKLOG_ELAPSED_FIELD_ID,
          PRODUCTION_CARD_AJTOLAPOK_FIELD_ID,
          PRODUCTION_CARD_TOKLEC_KESZ_FIELD_ID,
          PRODUCTION_CARD_KULSO_LAP_KESZ_FIELD_ID,
          PRODUCTION_CARD_BELSO_LAP_KESZ_FIELD_ID,
          PRODUCTION_CARD_LAP_TOKLEC_KESZ_FIELD_ID,
          PRODUCTION_CARD_KISZALLITASI_DATUM_FIELD_ID,
          ...(
            dataSource === "production-plan"
              ? validFields.filter(isProductionCardCrossStationStatusField)
              : []
          ),
        ].filter((fieldId) =>
          validFieldSet.has(fieldId)
          && !table.fieldOrder.includes(fieldId)
        );

        const nextHiddenFieldIds = Array.from(new Set([
          ...table.hiddenFieldIds.filter((fieldId) =>
            validFieldSet.has(fieldId)
            && !(dataSource === "production-plan" && isRequiredProductionCardField(fieldId))
          ),
          ...newlyAddedOptionalFields,
        ]));
        return {
          ...table,
          dataSource,
          name: table.name || `Táblázat ${index + 1}`,
          title: table.title || table.name || `Táblázat ${index + 1}`,
          fieldOrder: nextFieldOrder,
          hiddenFieldIds: nextHiddenFieldIds,
          fieldStyles: Object.fromEntries(
            Object.entries(table.fieldStyles || {}).filter(([fieldId]) => validFieldSet.has(fieldId))
          ),
        };
      })
    : createDefaultProductionCardProfile(stationName).tables;

  const priorityCandidates = tables.filter((table) => table.dataSource === "priority");
  const existingPriorityTable =
    priorityCandidates.find((table) => table.id === "card-table-priority")
    || priorityCandidates[0];

  const existingBacklogTable = tables.find((table) => table.dataSource === "backlog");

  // A régi hibás profilokban a Prioritási kártya production-plan típusú
  // másolatként is bent maradhatott. Ezeket nem engedjük vissza a normál kártyák közé.
  const productionTables = tables.filter(
    (table) =>
      table.dataSource === "production-plan"
      && !isLegacyPriorityProductionCardTable(table)
  );
  const priorityTable = existingPriorityTable || createDefaultPriorityCardTable(normalized.theme, stationName);
  const backlogTable = existingBacklogTable || createDefaultBacklogCardTable(normalized.theme, stationName);
  if (scrapReplacementStation) {
    const existingScrapTable = tables.find((table) => table.dataSource === "scrap-replacement");
    tables = [
      priorityTable,
      existingScrapTable || createDefaultScrapReplacementCardTable(normalized.theme),
      backlogTable,
      ...productionTables,
    ];
  } else {
    tables = [priorityTable, backlogTable, ...productionTables];
  }

  if (tables.length === 0) tables = createDefaultProductionCardProfile(stationName).tables;

  return sanitizeProductionCardProfile({
    ...normalized,
    id: normalized.id || `production-card-${stationName}`,
    name: normalized.name || `${stationName} termelési kártya`,
    tables,
    activeTableId: tables.some((table) => table.id === normalized.activeTableId)
      ? normalized.activeTableId
      : tables.find((table) => table.dataSource === "production-plan")?.id || tables[0].id,
  });
}

function normalizeProductionMonitorFieldStyle(value: unknown): ProductionMonitorFieldStyle {
  const raw = value && typeof value === "object" ? value as Partial<ProductionMonitorFieldStyle> : {};
  const widthWeight = Number(raw.widthWeight);
  const validAlignments: ProductionMonitorTextAlign[] = ["left", "center", "right"];
  const validTriStates: ProductionMonitorTriState[] = ["inherit", "yes", "no"];
  return {
    widthWeight: Number.isFinite(widthWeight) ? Math.min(8, Math.max(0.25, widthWeight)) : 1,
    textAlign: validAlignments.includes(raw.textAlign as ProductionMonitorTextAlign)
      ? raw.textAlign as ProductionMonitorTextAlign
      : "center",
    headerBackground: typeof raw.headerBackground === "string" ? raw.headerBackground : "",
    headerTextColor: typeof raw.headerTextColor === "string" ? raw.headerTextColor : "",
    cellBackground: typeof raw.cellBackground === "string" ? raw.cellBackground : "",
    cellTextColor: typeof raw.cellTextColor === "string" ? raw.cellTextColor : "",
    headerBold: validTriStates.includes(raw.headerBold as ProductionMonitorTriState)
      ? raw.headerBold as ProductionMonitorTriState
      : "inherit",
    headerItalic: validTriStates.includes(raw.headerItalic as ProductionMonitorTriState)
      ? raw.headerItalic as ProductionMonitorTriState
      : "inherit",
    cellBold: validTriStates.includes(raw.cellBold as ProductionMonitorTriState)
      ? raw.cellBold as ProductionMonitorTriState
      : "inherit",
    cellItalic: validTriStates.includes(raw.cellItalic as ProductionMonitorTriState)
      ? raw.cellItalic as ProductionMonitorTriState
      : "inherit",
  };
}

function normalizeProductionMonitorTheme(value: unknown): ProductionMonitorTheme {
  const raw = value && typeof value === "object" ? value as Partial<ProductionMonitorTheme> : {};
  const defaults = DEFAULT_PRODUCTION_MONITOR_THEME;
  const numberValue = (candidate: unknown, fallback: number, minimum: number, maximum: number): number => {
    const parsed = Number(candidate);
    return Number.isFinite(parsed) ? Math.min(maximum, Math.max(minimum, parsed)) : fallback;
  };
  const booleanValue = (candidate: unknown, fallback: boolean): boolean =>
    typeof candidate === "boolean" ? candidate : fallback;
  const stringValue = (candidate: unknown, fallback: string): string =>
    typeof candidate === "string" && candidate.trim() ? candidate : fallback;

  return {
    fontFamily: stringValue(raw.fontFamily, defaults.fontFamily),
    baseFontSize: numberValue(raw.baseFontSize, defaults.baseFontSize, 7, 28),
    titleFontSize: numberValue(raw.titleFontSize, defaults.titleFontSize, 16, 72),
    titleBold: booleanValue(raw.titleBold, defaults.titleBold),
    titleItalic: booleanValue(raw.titleItalic, defaults.titleItalic),
    tableTitleFontSize: numberValue(raw.tableTitleFontSize, defaults.tableTitleFontSize, 12, 48),
    tableTitleBold: booleanValue(raw.tableTitleBold, defaults.tableTitleBold),
    tableTitleItalic: booleanValue(raw.tableTitleItalic, defaults.tableTitleItalic),
    headerFontSize: numberValue(raw.headerFontSize, defaults.headerFontSize, 0, 36),
    cellFontSize: numberValue(raw.cellFontSize, defaults.cellFontSize, 0, 36),
    headerBold: booleanValue(raw.headerBold, defaults.headerBold),
    headerItalic: booleanValue(raw.headerItalic, defaults.headerItalic),
    cellBold: booleanValue(raw.cellBold, defaults.cellBold),
    cellItalic: booleanValue(raw.cellItalic, defaults.cellItalic),
    pageBackground: stringValue(raw.pageBackground, defaults.pageBackground),
    headerPanelBackground: stringValue(raw.headerPanelBackground, defaults.headerPanelBackground),
    headerPanelText: stringValue(raw.headerPanelText, defaults.headerPanelText),
    subtitleText: stringValue(raw.subtitleText, defaults.subtitleText),
    accentColor: stringValue(raw.accentColor, defaults.accentColor),
    editorBackground: stringValue(raw.editorBackground, defaults.editorBackground),
    tablePanelBackground: stringValue(raw.tablePanelBackground, defaults.tablePanelBackground),
    tableTitleText: stringValue(raw.tableTitleText, defaults.tableTitleText),
    tableHeaderBackground: stringValue(raw.tableHeaderBackground, defaults.tableHeaderBackground),
    tableHeaderText: stringValue(raw.tableHeaderText, defaults.tableHeaderText),
    orderCellBackground: stringValue(raw.orderCellBackground, defaults.orderCellBackground),
    orderCellText: stringValue(raw.orderCellText, defaults.orderCellText),
    doneBackground: stringValue(raw.doneBackground, defaults.doneBackground),
    doneText: stringValue(raw.doneText, defaults.doneText),
    inProgressBackground: stringValue(raw.inProgressBackground, defaults.inProgressBackground),
    inProgressText: stringValue(raw.inProgressText, defaults.inProgressText),
    waitingBackground: stringValue(raw.waitingBackground, defaults.waitingBackground),
    waitingText: stringValue(raw.waitingText, defaults.waitingText),
    notRequiredBackground: stringValue(raw.notRequiredBackground, defaults.notRequiredBackground),
    notRequiredText: stringValue(raw.notRequiredText, defaults.notRequiredText),
    borderColor: stringValue(raw.borderColor, defaults.borderColor),
    panelRadius: numberValue(raw.panelRadius, defaults.panelRadius, 0, 40),
    contentMaxWidth: numberValue(raw.contentMaxWidth, defaults.contentMaxWidth, 800, 2600),
    headerPadding: numberValue(raw.headerPadding, defaults.headerPadding, 2, 28),
    cellPadding: numberValue(raw.cellPadding, defaults.cellPadding, 2, 28),
    showHeader: booleanValue(raw.showHeader, defaults.showHeader),
    showPlanInfo: booleanValue(raw.showPlanInfo, defaults.showPlanInfo),
    showLastUpdated: booleanValue(raw.showLastUpdated, defaults.showLastUpdated),
    showSummaryCards: booleanValue(raw.showSummaryCards, defaults.showSummaryCards),
  };
}

function normalizeReadableHexColor(value: string): string | null {
  const input = String(value || "").trim();
  if (/^#[0-9a-fA-F]{6}$/.test(input)) return input.toUpperCase();
  if (/^#[0-9a-fA-F]{3}$/.test(input)) {
    const raw = input.slice(1);
    return `#${raw[0]}${raw[0]}${raw[1]}${raw[1]}${raw[2]}${raw[2]}`.toUpperCase();
  }
  return null;
}

function productionCardRelativeLuminance(color: string): number | null {
  const hex = normalizeReadableHexColor(color);
  if (!hex) return null;
  const channel = (offset: number): number => {
    const value = parseInt(hex.slice(offset, offset + 2), 16) / 255;
    return value <= 0.03928 ? value / 12.92 : Math.pow((value + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * channel(1) + 0.7152 * channel(3) + 0.0722 * channel(5);
}

function productionCardContrastRatio(background: string, foreground: string): number {
  const backgroundLuminance = productionCardRelativeLuminance(background);
  const foregroundLuminance = productionCardRelativeLuminance(foreground);
  if (backgroundLuminance === null || foregroundLuminance === null) return 21;
  const lighter = Math.max(backgroundLuminance, foregroundLuminance);
  const darker = Math.min(backgroundLuminance, foregroundLuminance);
  return (lighter + 0.05) / (darker + 0.05);
}

function ensureReadableProductionCardTextColor(background: string, preferred: string, minimumContrast = 4.5): string {
  const backgroundHex = normalizeReadableHexColor(background);
  const preferredHex = normalizeReadableHexColor(preferred);
  if (!backgroundHex) return preferred;
  if (preferredHex && productionCardContrastRatio(backgroundHex, preferredHex) >= minimumContrast) return preferredHex;
  const blackContrast = productionCardContrastRatio(backgroundHex, "#000000");
  const whiteContrast = productionCardContrastRatio(backgroundHex, "#FFFFFF");
  return blackContrast >= whiteContrast ? "#000000" : "#FFFFFF";
}

function sanitizeProductionCardTheme(value: ProductionMonitorTheme): ProductionMonitorTheme {
  const theme = normalizeProductionMonitorTheme(value);
  return {
    ...theme,
    headerPanelText: ensureReadableProductionCardTextColor(theme.headerPanelBackground, theme.headerPanelText, 4.5),
    subtitleText: ensureReadableProductionCardTextColor(theme.headerPanelBackground, theme.subtitleText, 3.5),
    accentColor: ensureReadableProductionCardTextColor(theme.headerPanelBackground, theme.accentColor, 3.0),
    tableTitleText: ensureReadableProductionCardTextColor(theme.tablePanelBackground, theme.tableTitleText, 4.5),
    tableHeaderText: ensureReadableProductionCardTextColor(theme.tableHeaderBackground, theme.tableHeaderText, 4.5),
    orderCellText: ensureReadableProductionCardTextColor(theme.orderCellBackground, theme.orderCellText, 4.5),
    doneText: ensureReadableProductionCardTextColor(theme.doneBackground, theme.doneText, 4.5),
    inProgressText: ensureReadableProductionCardTextColor(theme.inProgressBackground, theme.inProgressText, 4.5),
    waitingText: ensureReadableProductionCardTextColor(theme.waitingBackground, theme.waitingText, 4.5),
    notRequiredText: ensureReadableProductionCardTextColor(theme.notRequiredBackground, theme.notRequiredText, 3.5),
  };
}

function sanitizeProductionCardFieldStyle(value: ProductionMonitorFieldStyle, theme: ProductionMonitorTheme): ProductionMonitorFieldStyle {
  const style = normalizeProductionMonitorFieldStyle(value);
  const safeTheme = sanitizeProductionCardTheme(theme);
  const headerBackground = style.headerBackground || safeTheme.tableHeaderBackground;
  const cellBackground = style.cellBackground || safeTheme.waitingBackground;
  return {
    ...style,
    headerTextColor: style.headerBackground || style.headerTextColor
      ? ensureReadableProductionCardTextColor(headerBackground, style.headerTextColor || safeTheme.tableHeaderText, 4.5)
      : style.headerTextColor,
    cellTextColor: style.cellBackground || style.cellTextColor
      ? ensureReadableProductionCardTextColor(cellBackground, style.cellTextColor || safeTheme.waitingText, 4.5)
      : style.cellTextColor,
  };
}

function sanitizeProductionCardProfile(profile: ProductionMonitorProfile): ProductionMonitorProfile {
  const safeProfileTheme = sanitizeProductionCardTheme(profile.theme);
  const singletonDataSources = new Set<ProductionCardTableDataSource>([
    "priority",
    "scrap-replacement",
    "backlog",
  ]);
  const seenSingletonDataSources = new Set<ProductionCardTableDataSource>();

  const canonicalTables = profile.tables.map((table) =>
    isLegacyPriorityProductionCardTable(table)
      ? { ...table, dataSource: "priority" as ProductionCardTableDataSource }
      : table
  );

  const safeTables = canonicalTables
    .filter((table) => {
      const dataSource = table.dataSource as ProductionCardTableDataSource;
      if (!singletonDataSources.has(dataSource)) return true;

      // A rendszer által automatikusan biztosított elsőbbségi kártyákból
      // munkaállomásonként és típusonként pontosan EGY példány lehet.
      if (seenSingletonDataSources.has(dataSource)) return false;
      seenSingletonDataSources.add(dataSource);
      return true;
    })
    .map((table) => {
      const safeTableTheme = sanitizeProductionCardTheme(table.theme || safeProfileTheme);
      return {
        ...table,
        theme: safeTableTheme,
        // Állapot / Indító dolgozó / Befejező dolgozó normál termelési
        // kártyán soha nem kerülhet a rejtett mezők közé.
        hiddenFieldIds: table.dataSource === "production-plan"
          ? table.hiddenFieldIds.filter((fieldId) => !isRequiredProductionCardField(fieldId))
          : table.hiddenFieldIds,
        fieldStyles: Object.fromEntries(
          Object.entries(table.fieldStyles || {}).map(([fieldId, style]) => [
            fieldId,
            sanitizeProductionCardFieldStyle(style, safeTableTheme),
          ])
        ),
      };
    });

  const safeActiveTableId = safeTables.some((table) => table.id === profile.activeTableId)
    ? profile.activeTableId
    : safeTables.find((table) => table.dataSource === "production-plan")?.id
      || safeTables[0]?.id
      || "";

  return {
    ...profile,
    theme: safeProfileTheme,
    tables: safeTables,
    activeTableId: safeActiveTableId,
  };
}

function normalizeProductionMonitorTable(value: unknown, index: number, fallbackTheme: ProductionMonitorTheme): ProductionMonitorTableConfig {
  const raw = value && typeof value === "object" ? value as Partial<ProductionMonitorTableConfig> : {};
  const fallback = createDefaultProductionMonitorTable(`Táblázat ${index + 1}`, `table-${index + 1}`, fallbackTheme);
  const rawFieldStyles = raw.fieldStyles && typeof raw.fieldStyles === "object" ? raw.fieldStyles : {};
  return {
    id: typeof raw.id === "string" && raw.id.trim() ? raw.id : fallback.id,
    name: typeof raw.name === "string" && raw.name.trim() ? raw.name.slice(0, 80) : fallback.name,
    title: typeof raw.title === "string" && raw.title.trim() ? raw.title.slice(0, 120) : (typeof raw.name === "string" && raw.name.trim() ? raw.name.slice(0, 120) : fallback.title),
    fieldOrder: Array.isArray(raw.fieldOrder) ? raw.fieldOrder.filter((item): item is string => typeof item === "string") : [],
    hiddenFieldIds: Array.isArray(raw.hiddenFieldIds) ? raw.hiddenFieldIds.filter((item): item is string => typeof item === "string") : [],
    theme: normalizeProductionMonitorTheme(raw.theme || fallbackTheme),
    fieldStyles: Object.fromEntries(
      Object.entries(rawFieldStyles).map(([fieldId, style]) => [fieldId, normalizeProductionMonitorFieldStyle(style)])
    ),
    dataSource: raw.dataSource === "priority"
      ? "priority"
      : raw.dataSource === "scrap-replacement"
        ? "scrap-replacement"
        : raw.dataSource === "backlog"
          ? "backlog"
          : "production-plan",
  };
}

function normalizeProductionMonitorProfile(value: unknown, index: number): ProductionMonitorProfile {
  const raw = value && typeof value === "object" ? value as Partial<ProductionMonitorProfile> & {
    fieldOrder?: string[];
    hiddenFieldIds?: string[];
    fieldStyles?: Record<string, unknown>;
  } : {};
  const inferredFilter: ProductionMonitorPlanStatusFilter =
    normalizeLooseText(String(raw.name || raw.id || "")).includes("kerites")
      ? "kerites"
      : "ajto";
  const rawFilter = String((raw as { planStatusFilter?: unknown }).planStatusFilter || "");
  const planStatusFilter: ProductionMonitorPlanStatusFilter = rawFilter === "kerites" || rawFilter === "ajto"
    ? rawFilter
    : inferredFilter;
  const fallback = createDefaultProductionMonitorProfile(`Monitor ${index + 1}`, `monitor-${index + 1}`, planStatusFilter);
  const profileTheme = normalizeProductionMonitorTheme(raw.theme);
  let tables: ProductionMonitorTableConfig[] = [];

  if (Array.isArray(raw.tables) && raw.tables.length > 0) {
    tables = raw.tables.map((table, tableIndex) => normalizeProductionMonitorTable(table, tableIndex, profileTheme));
  } else {
    const legacyTable = normalizeProductionMonitorTable({
      id: "table-default",
      name: "Termelési állapot",
      title: "Termelési állapot",
      fieldOrder: raw.fieldOrder,
      hiddenFieldIds: raw.hiddenFieldIds,
      theme: raw.theme,
      fieldStyles: raw.fieldStyles,
    }, 0, profileTheme);
    tables = [legacyTable];
  }

  const validPresetIds: ProductionMonitorThemePresetId[] = ["industrial-night", "premium-light", "control-room", "steel-blue", "graphite-amber", "custom"];
  const requestedActiveTableId = typeof raw.activeTableId === "string" ? raw.activeTableId : "";
  const activeTableId = tables.some((table) => table.id === requestedActiveTableId) ? requestedActiveTableId : tables[0].id;

  return {
    id: typeof raw.id === "string" && raw.id.trim() ? raw.id : fallback.id,
    name: typeof raw.name === "string" && raw.name.trim() ? raw.name.slice(0, 80) : fallback.name,
    planStatusFilter,
    themePresetId: validPresetIds.includes(raw.themePresetId as ProductionMonitorThemePresetId)
      ? raw.themePresetId as ProductionMonitorThemePresetId
      : "custom",
    zoomPercent: typeof raw.zoomPercent === "number" && Number.isFinite(raw.zoomPercent)
      ? Math.min(PRODUCTION_MONITOR_MAX_ZOOM, Math.max(PRODUCTION_MONITOR_MIN_ZOOM, Math.round(raw.zoomPercent)))
      : 100,
    theme: profileTheme,
    tables,
    activeTableId,
  };
}

function resolveProductionMonitorTriState(value: ProductionMonitorTriState, fallback: boolean): boolean {
  if (value === "yes") return true;
  if (value === "no") return false;
  return fallback;
}

type MachineIdOption = string;

function normalizeMachineId(value: string | null | undefined): MachineIdOption {
  const cleanValue = String(value || "").trim();
  return cleanValue || DEFAULT_MACHINE_ID;
}

function readMachineIdFromStorage(): MachineIdOption {
  if (typeof window === "undefined") return DEFAULT_MACHINE_ID;
  try {
    const stored = window.localStorage.getItem(MACHINE_ID_STORAGE_KEY);
    const normalized = normalizeMachineId(stored);
    if (!stored) {
      window.localStorage.setItem(MACHINE_ID_STORAGE_KEY, normalized);
    }
    return normalized;
  } catch {
    return DEFAULT_MACHINE_ID;
  }
}

function writeMachineIdToStorage(value: string): MachineIdOption {
  const normalized = normalizeMachineId(value);
  if (typeof window !== "undefined") {
    try {
      window.localStorage.setItem(MACHINE_ID_STORAGE_KEY, normalized);
    } catch {
      // localStorage hiba esetén a rendszer továbbra is Mobil eszközként tud lejelenteni.
    }
  }
  return normalized;
}

function normalizeMachineIdFromOptions(value: string | null | undefined, options: string[]): string {
  const cleanValue = String(value || "").trim();
  const normalizedOptions = [DEFAULT_MACHINE_ID, ...options.filter((option) => option.trim())];
  const matched = normalizedOptions.find((option) => option.toLowerCase() === cleanValue.toLowerCase());
  return matched || DEFAULT_MACHINE_ID;
}

function buildMachineOptions(rows: MachineIdRow[]): string[] {
  const unique = new Map<string, string>();

  for (const row of rows) {
    const rawName =
      row.name ??
      row.Name ??
      row.machine_name ??
      row.machine_id ??
      row.megnevezes ??
      null;

    const name = String(rawName || "").trim();
    if (name) unique.set(name.toLowerCase(), name);
  }

  // A machine_id táblából érkező sorrendet változtatás nélkül megtartjuk.
  return Array.from(unique.values());
}

async function fetchMachineIdRowsDirectly(): Promise<MachineIdRow[]> {
  if (typeof fetch === "undefined") return [];

  const endpoints = [
    `${SUPABASE_URL}/rest/v1/machine_id?select=*&order=id.asc`,
    `${SUPABASE_URL}/rest/v1/machine_id?select=id,name&order=id.asc`,
  ];

  for (const endpoint of endpoints) {
    try {
      const response = await fetch(endpoint, {
        method: "GET",
        headers: {
          apikey: SUPABASE_ANON_KEY,
          Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
          Accept: "application/json",
        },
      });

      if (!response.ok) continue;

      const json = await response.json();
      if (Array.isArray(json) && json.length > 0) {
        return json as MachineIdRow[];
      }
    } catch (error) {
      console.error("SUPABASE REST fallback machine_id hiba:", error);
    }
  }

  return [];
}

async function ensureProductionBatchStartMachineSaved(
  supabase: SupabaseClient,
  params: {
    id?: string | number | null;
    batchCode?: string | null;
    startTime: string;
    machineId: string;
  }
): Promise<void> {
  const payload = {
    start_time: params.startTime,
    machine_id: params.machineId,
  };

  let query = supabase.from("production_batches").update(payload);

  if (params.id !== undefined && params.id !== null && String(params.id).trim() !== "") {
    query = query.eq("id", params.id);
  } else if (params.batchCode && params.batchCode.trim()) {
    query = query.eq("batch_code", params.batchCode.trim());
  } else {
    return;
  }

  const { error } = await query;
  if (error) throw error;
}
