      const currentWidth = terminalEntryLayoutCanvasRef.current?.clientWidth || window.innerWidth;
      setTerminalEntryLayoutViewportWidth(Math.max(TERMINAL_ENTRY_LAYOUT_MIN_WIDTH, currentWidth));
