  const filteredStatsRows = useMemo(() => {
    const q = statsFilter.trim().toLowerCase();
    const fromTime = statsDateFrom ? new Date(`${statsDateFrom}T00:00:00`).getTime() : null;
    const toTime = statsDateTo ? new Date(`${statsDateTo}T23:59:59.999`).getTime() : null;

    return statsRows
      .map((row) => {
        const segments = row.segments.filter((segment) => {
          const segmentTime = new Date(segment.startAt).getTime();
          const matchesDate =
            (fromTime === null || segmentTime >= fromTime) &&
            (toTime === null || segmentTime <= toTime);
          const haystack = [
            row.orderNumber,
            row.lastRole,
            row.lastWorkerName,
            segment.role,
            segment.station,
            segment.workerName,
            segment.status,
          ]
            .join(" ")
            .toLowerCase();
          const matchesText = !q || haystack.includes(q);
          return matchesDate && matchesText;
        });
        if (segments.length === 0) return null;
        const latestSegment = [...segments].sort(
          (a, b) => new Date(b.endAt || b.startAt).getTime() - new Date(a.endAt || a.startAt).getTime()
        )[0];
        const totalMinutes = segments.reduce((sum, item) => sum + item.durationMinutes, 0);
        const openSegmentCount = segments.filter((item) => item.status === "folyamatban").length;
        return {
          ...row,
          segments,
          totalMinutes,
          totalDurationLabel: formatDuration(totalMinutes),
          lastRole: latestSegment?.role || row.lastRole,
          lastWorkerName: latestSegment?.workerName || row.lastWorkerName,
          lastEventTime: latestSegment?.endAt || latestSegment?.startAt || row.lastEventTime,
          openSegmentCount,
          hasOpenSegments: openSegmentCount > 0,
          statusLabel: openSegmentCount > 0 ? "Lezáratlan / hiányzó END" : "Lezárt",
        };
      })
      .filter((row): row is OrderStatsRow => !!row)
      .sort((a, b) => new Date(b.lastEventTime).getTime() - new Date(a.lastEventTime).getTime());
  }, [statsRows, statsFilter, statsDateFrom, statsDateTo]);

  const roleSummary = useMemo(() => {
    const summary = new Map<
      string,
      {
        role: string;
        totalMinutes: number;
        orders: Set<string>;
        openCount: number;
      }
    >();

    filteredStatsRows.forEach((row) => {
      row.segments.forEach((segment) => {
        const key = segment.role || "Ismeretlen munkakör";
        if (!summary.has(key)) {
          summary.set(key, {
            role: key,
            totalMinutes: 0,
            orders: new Set<string>(),
            openCount: 0,
          });
        }
        const item = summary.get(key)!;
        item.totalMinutes += segment.durationMinutes;
        item.orders.add(row.orderNumber);
        if (segment.status === "folyamatban") item.openCount += 1;
      });
    });

    return Array.from(summary.values())
      .map((item) => ({
        ...item,
        totalDurationLabel: formatDuration(item.totalMinutes),
        orderCount: item.orders.size,
      }))
      .sort((a, b) => b.totalMinutes - a.totalMinutes);
  }, [filteredStatsRows]);

