  function getWorkerEntryBackground(stationName: string): string {
    const normalizedStation = normalizeLooseText(stationName);
    const matchedEntry = Object.entries(workerEntryBackgroundByStation).find(
      ([name]) => normalizeLooseText(name) === normalizedStation
    );
    return matchedEntry?.[1] || DEFAULT_WORKER_ENTRY_BACKGROUND;
  }

  function setWorkerEntryBackgroundLocal(stationName: string, color: string): void {
    const cleanStation = String(stationName || "").trim();
    if (!cleanStation) return;

    const normalizedColor = normalizeReadableHexColor(color) || DEFAULT_WORKER_ENTRY_BACKGROUND;
    setWorkerEntryBackgroundByStation((current) => ({
      ...current,
      [cleanStation]: normalizedColor,
    }));
  }

  async function loadWorkerEntryBackgroundSettings(): Promise<void> {
    if (!supabase) return;
    try {
      const response = await supabase
        .from(WORKER_ENTRY_BACKGROUND_SETTINGS_TABLE)
        .select("station_name, background_color")
        .limit(10000);

      if (response.error) {
        console.warn("Dolgozói beléptető háttérbeállítások nem olvashatók:", response.error);
        return;
      }

      const next: Record<string, string> = {};
      ((response.data || []) as Array<Record<string, unknown>>).forEach((row) => {
        const stationName = String(row.station_name || "").trim();
        const color = normalizeReadableHexColor(String(row.background_color || ""));
        if (stationName && color) next[stationName] = color;
      });
      setWorkerEntryBackgroundByStation(next);
    } catch (error) {
      console.warn("Dolgozói beléptető háttér betöltési hiba:", error);
    }
  }

  async function persistWorkerEntryBackground(
    stationName: string,
    color: string,
    showMessage = false
  ): Promise<void> {
    if (!supabase) return;

    const cleanStation = String(stationName || "").trim();
    if (!cleanStation) return;

    const normalizedColor = normalizeReadableHexColor(color) || DEFAULT_WORKER_ENTRY_BACKGROUND;
    setWorkerEntryBackgroundSaveState("saving");

    try {
      const response = await supabase
        .from(WORKER_ENTRY_BACKGROUND_SETTINGS_TABLE)
        .upsert({
          station_name: cleanStation,
          background_color: normalizedColor,
          updated_by_worker_name: String(activeWorker?.["Teljes nev"] || "").trim() || null,
          updated_at: new Date().toISOString(),
        }, { onConflict: "station_name" });

      if (response.error) throw response.error;

      setWorkerEntryBackgroundLocal(cleanStation, normalizedColor);
      setWorkerEntryBackgroundSaveState("saved");
      if (showMessage) {
        setMessage({
          type: "success",
          text: `A(z) ${cleanStation} dolgozói beléptető háttere elmentve.`,
        });
      }
    } catch (error) {
      setWorkerEntryBackgroundSaveState("error");
      if (showMessage) {
        setMessage({
          type: "error",
          text: `A dolgozói beléptető háttér mentése sikertelen: ${normalizeError(error)}`,
        });
      } else {
        console.warn("Dolgozói beléptető háttér automatikus mentési hiba:", error);
      }
    }
  }

  function queueWorkerEntryBackgroundSave(stationName: string, color: string): void {
    const key = `worker-entry-background:${normalizeLooseText(stationName)}`;
    const currentTimer = officeUiAutoSaveTimersRef.current[key];
    if (currentTimer) clearTimeout(currentTimer);

    officeUiAutoSaveTimersRef.current[key] = setTimeout(() => {
      delete officeUiAutoSaveTimersRef.current[key];
      void persistWorkerEntryBackground(stationName, color, false);
    }, 500);
  }

  function updateWorkerEntryBackground(stationName: string, color: string): void {
    const normalizedColor = normalizeReadableHexColor(color);
    if (!normalizedColor) return;
    setWorkerEntryBackgroundLocal(stationName, normalizedColor);
    queueWorkerEntryBackgroundSave(stationName, normalizedColor);
  }

  function resetWorkerEntryBackground(stationName: string): void {
    setWorkerEntryBackgroundLocal(stationName, DEFAULT_WORKER_ENTRY_BACKGROUND);
    queueWorkerEntryBackgroundSave(stationName, DEFAULT_WORKER_ENTRY_BACKGROUND);
  }

  function getOfficeTheme(pageKey: OfficePageKey = managementSection): OfficeThemeConfig {
    return officeThemeByPage[pageKey] || cloneOfficeTheme(OFFICE_THEME_PRESETS["industrial-night"].theme);
  }

  function officeWindowStateKey(pageKey: OfficePageKey, windowKey: string): string {
    return `${pageKey}:${windowKey}`;
  }

  function officeWindowDbKey(pageKey: OfficePageKey, windowKey: string): string {
    return `${OFFICE_WINDOW_UI_PREFIX}${pageKey}:${windowKey}`;
  }

  function getOfficeWindowTheme(pageKey: OfficePageKey, windowKey: string): OfficeThemeConfig {
    const key = officeWindowStateKey(pageKey, windowKey);
    return officeWindowThemeByKey[key] || getOfficeTheme(pageKey);
  }

  function getOfficeWindowPreset(pageKey: OfficePageKey, windowKey: string): OfficeThemePresetId {
    return officeWindowPresetByKey[officeWindowStateKey(pageKey, windowKey)] || officeThemePresetByPage[pageKey] || "industrial-night";
  }

  function getOfficeWindowDefinitions(pageKey: OfficePageKey): OfficeWindowDefinition[] {
    return OFFICE_WINDOW_DEFINITIONS[pageKey] || [];
  }

  function buildOfficeWindowCss(pageKey: OfficePageKey): string {
    return getOfficeWindowDefinitions(pageKey).map((windowDef) => {
      const theme = getOfficeWindowTheme(pageKey, windowDef.id);
      const selector = `[data-office-window="${pageKey}:${windowDef.id}"]`;
      const shadowAlpha = Math.max(0, Math.min(1, theme.shadowOpacity));
      return `
${selector} {
  background: ${theme.panelBackground} !important;
  color: ${theme.textColor} !important;
  border-color: ${theme.borderColor} !important;
  border-width: ${theme.borderWidth}px !important;
  border-style: solid !important;
  border-radius: ${theme.borderRadius}px !important;
  font-family: ${theme.fontFamily} !important;
  font-size: ${theme.baseFontSize}px !important;
  box-shadow: 0 8px ${theme.shadowBlur}px rgba(0,0,0,${shadowAlpha}) !important;
}
${selector} h1, ${selector} h2, ${selector} h3, ${selector} h4, ${selector} strong { color: ${theme.textColor} !important; font-family: ${theme.fontFamily} !important; }
${selector} h1, ${selector} h2 { font-size: ${theme.titleFontSize}px !important; font-weight: ${theme.fontWeight} !important; }
${selector} input:not([type="color"]), ${selector} select, ${selector} textarea {
  background: ${theme.inputBackground} !important;
  color: ${theme.inputText} !important;
  border-color: ${theme.borderColor} !important;
  border-width: ${theme.borderWidth}px !important;
  border-radius: ${Math.max(4, theme.borderRadius - 5)}px !important;
  min-height: ${theme.fieldHeight}px !important;
  font-family: ${theme.fontFamily} !important;
  font-size: ${theme.baseFontSize}px !important;
}
${selector} button {
  font-family: ${theme.fontFamily} !important;
  border-radius: ${Math.max(4, theme.borderRadius - 5)}px !important;
  border-color: ${theme.borderColor} !important;
  color: ${theme.buttonText} !important;
}
${selector} button:not([data-preserve-action-color="true"]) { background: ${theme.secondaryButtonBackground} !important; }
${selector} button:hover:not(:disabled) { box-shadow: 0 0 ${Math.max(0, Math.round(theme.shadowBlur * .65))}px ${theme.accentColor} !important; }
${selector} table { color: ${theme.textColor} !important; font-family: ${theme.fontFamily} !important; background: ${theme.sectionBackground} !important; }
${selector} thead, ${selector} th { background: ${theme.headerBackground} !important; color: ${theme.textColor} !important; border-color: ${theme.borderColor} !important; }
${selector} tbody, ${selector} td { color: ${theme.textColor} !important; border-color: ${theme.borderColor} !important; }
${selector} label, ${selector} p, ${selector} span { font-family: ${theme.fontFamily} !important; }
${selector} > section, ${selector} > article { border-color: ${theme.borderColor} !important; }
`;
    }).join("\n");
  }

  async function persistOfficeUiPreference(dbPageKey: string, preset: OfficeThemePresetId, theme: OfficeThemeConfig, showMessage = false): Promise<void> {
    if (!supabase || !activeWorker || !isManagementDashboardWorker(activeWorker)) return;
    const workerName = String(activeWorker["Teljes nev"] || "").trim();
    if (!workerName) return;
    setOfficeUiAutoSaveState("saving");
    try {
      const existingResponse = await supabase
        .from("user_ui_preferences")
        .select("theme_preset, theme_json")
        .eq("worker_name", workerName)
        .eq("page_key", dbPageKey)
        .limit(1);
      if (existingResponse.error) throw existingResponse.error;
      const existing = (existingResponse.data || [])[0] as { theme_preset?: string | null; theme_json?: Record<string, unknown> | null } | undefined;
      const payload: Record<string, unknown> = {
        worker_name: workerName,
        worker_id: activeWorker.id,
        page_key: dbPageKey,
        theme_preset: preset,
        theme_json: ensureReadableOfficeTheme(theme),
        updated_at: new Date().toISOString(),
      };
      if (existing) {
        payload.previous_theme_preset = String(existing.theme_preset || "industrial-night");
        payload.previous_theme_json = existing.theme_json || {};
      }
      const response = await supabase.from("user_ui_preferences").upsert(payload, { onConflict: "worker_name,page_key" });
      if (response.error) throw response.error;
      setOfficeUiAutoSaveState("saved");
      if (showMessage) setMessage({ type: "success", text: "A megjelenés elmentve a felhasználódhoz." });
    } catch (error) {
      setOfficeUiAutoSaveState("error");
      if (showMessage) setMessage({ type: "error", text: `A megjelenési beállítás mentése sikertelen: ${normalizeError(error)}` });
      else console.warn("Automatikus UI mentési hiba:", error);
    }
  }

  function queueOfficeUiPreferenceSave(dbPageKey: string, preset: OfficeThemePresetId, theme: OfficeThemeConfig): void {
    const currentTimer = officeUiAutoSaveTimersRef.current[dbPageKey];
    if (currentTimer) clearTimeout(currentTimer);
    officeUiAutoSaveTimersRef.current[dbPageKey] = setTimeout(() => {
      delete officeUiAutoSaveTimersRef.current[dbPageKey];
      void persistOfficeUiPreference(dbPageKey, preset, theme, false);
    }, 650);
  }

  function applyOfficeThemePreset(pageKey: OfficePageKey, presetId: Exclude<OfficeThemePresetId, "custom">): void {
    const theme = cloneOfficeTheme(OFFICE_THEME_PRESETS[presetId].theme);
    setOfficeThemePresetByPage((current) => ({ ...current, [pageKey]: presetId }));
    setOfficeThemeByPage((current) => ({ ...current, [pageKey]: theme }));
    queueOfficeUiPreferenceSave(pageKey, presetId, theme);
  }

  function updateOfficeTheme(pageKey: OfficePageKey, patch: Partial<OfficeThemeConfig>): void {
    const nextTheme = ensureReadableOfficeTheme({ ...getOfficeTheme(pageKey), ...patch });
    setOfficeThemePresetByPage((current) => ({ ...current, [pageKey]: "custom" }));
    setOfficeThemeByPage((current) => ({ ...current, [pageKey]: nextTheme }));
    queueOfficeUiPreferenceSave(pageKey, "custom", nextTheme);
  }

  function applyOfficeWindowPreset(pageKey: OfficePageKey, windowKey: string, presetId: Exclude<OfficeThemePresetId, "custom">): void {
    const stateKey = officeWindowStateKey(pageKey, windowKey);
    const theme = cloneOfficeTheme(OFFICE_THEME_PRESETS[presetId].theme);
    setOfficeWindowPresetByKey((current) => ({ ...current, [stateKey]: presetId }));
    setOfficeWindowThemeByKey((current) => ({ ...current, [stateKey]: theme }));
    queueOfficeUiPreferenceSave(officeWindowDbKey(pageKey, windowKey), presetId, theme);
  }

  function updateOfficeWindowTheme(pageKey: OfficePageKey, windowKey: string, patch: Partial<OfficeThemeConfig>): void {
    const stateKey = officeWindowStateKey(pageKey, windowKey);
    const nextTheme = ensureReadableOfficeTheme({ ...getOfficeWindowTheme(pageKey, windowKey), ...patch });
    setOfficeWindowPresetByKey((current) => ({ ...current, [stateKey]: "custom" }));
    setOfficeWindowThemeByKey((current) => ({ ...current, [stateKey]: nextTheme }));
    queueOfficeUiPreferenceSave(officeWindowDbKey(pageKey, windowKey), "custom", nextTheme);
  }

  async function restorePreviousOfficeUiPreference(pageKey: OfficePageKey, windowKey?: string): Promise<void> {
    if (!supabase || !activeWorker) return;
    const workerName = String(activeWorker["Teljes nev"] || "").trim();
    if (!workerName) return;
    const dbPageKey = windowKey ? officeWindowDbKey(pageKey, windowKey) : pageKey;
    try {
      const response = await supabase
        .from("user_ui_preferences")
        .select("theme_preset, theme_json, previous_theme_preset, previous_theme_json")
        .eq("worker_name", workerName)
        .eq("page_key", dbPageKey)
        .limit(1);
      if (response.error) throw response.error;
      const row = (response.data || [])[0] as Record<string, unknown> | undefined;
      if (!row || !row.previous_theme_json || Object.keys((row.previous_theme_json || {}) as Record<string, unknown>).length === 0) {
        setMessage({ type:"info", text:"Ehhez a megjelenéshez még nincs korábbi mentett állapot." });
        return;
      }
      const previousPresetRaw = String(row.previous_theme_preset || "custom") as OfficeThemePresetId;
      const previousPreset: OfficeThemePresetId = previousPresetRaw === "custom" || Object.prototype.hasOwnProperty.call(OFFICE_THEME_PRESETS, previousPresetRaw) ? previousPresetRaw : "custom";
      const previousTheme = ensureReadableOfficeTheme({ ...getOfficeTheme(pageKey), ...((row.previous_theme_json || {}) as Partial<OfficeThemeConfig>) });
      const currentTheme = (row.theme_json || {}) as Record<string, unknown>;
      const currentPreset = String(row.theme_preset || "custom");
      const swapResponse = await supabase.from("user_ui_preferences").update({
        theme_preset: previousPreset,
        theme_json: previousTheme,
        previous_theme_preset: currentPreset,
        previous_theme_json: currentTheme,
        updated_at: new Date().toISOString(),
      }).eq("worker_name", workerName).eq("page_key", dbPageKey);
      if (swapResponse.error) throw swapResponse.error;
      if (windowKey) {
        const stateKey = officeWindowStateKey(pageKey, windowKey);
        setOfficeWindowPresetByKey((current) => ({ ...current, [stateKey]: previousPreset }));
        setOfficeWindowThemeByKey((current) => ({ ...current, [stateKey]: previousTheme }));
      } else {
        setOfficeThemePresetByPage((current) => ({ ...current, [pageKey]: previousPreset }));
        setOfficeThemeByPage((current) => ({ ...current, [pageKey]: previousTheme }));
      }
      setMessage({ type:"success", text:"Az előző megjelenési beállítás visszaállítva." });
    } catch (error) {
      setMessage({ type:"error", text:`Az előző megjelenés visszaállítása sikertelen: ${normalizeError(error)}` });
    }
  }

  function applyCurrentOfficeStyleToWholePage(pageKey: OfficePageKey, sourceTheme: OfficeThemeConfig, sourcePreset: OfficeThemePresetId): void {
    setOfficeThemeByPage((current) => ({ ...current, [pageKey]: cloneOfficeTheme(sourceTheme) }));
    setOfficeThemePresetByPage((current) => ({ ...current, [pageKey]: sourcePreset }));
    queueOfficeUiPreferenceSave(pageKey, sourcePreset, sourceTheme);
    const windows = getOfficeWindowDefinitions(pageKey);
    setOfficeWindowThemeByKey((current) => {
      const next = { ...current };
      windows.forEach((item) => { next[officeWindowStateKey(pageKey, item.id)] = cloneOfficeTheme(sourceTheme); });
      return next;
    });
    setOfficeWindowPresetByKey((current) => {
      const next = { ...current };
      windows.forEach((item) => { next[officeWindowStateKey(pageKey, item.id)] = sourcePreset; });
      return next;
    });
    windows.forEach((item) => queueOfficeUiPreferenceSave(officeWindowDbKey(pageKey, item.id), sourcePreset, sourceTheme));
    setMessage({ type:"success", text:"Az aktuális stílus az egész oldalra és minden szerkeszthető ablakra alkalmazva." });
  }

  async function loadOfficeUiPreferences(): Promise<void> {
    if (!supabase || !activeWorker || !isManagementDashboardWorker(activeWorker)) return;
    const workerName = String(activeWorker["Teljes nev"] || "").trim();
    if (!workerName) return;
    try {
      const response = await supabase.from("user_ui_preferences").select("page_key, theme_preset, theme_json").eq("worker_name", workerName);
      if (response.error) { console.warn("A user_ui_preferences tábla még nem olvasható:", response.error); return; }
      const nextThemes = createDefaultOfficeThemeMap();
      const nextPresets = createDefaultOfficeThemePresetMap();
      const nextWindowThemes: Record<string, OfficeThemeConfig> = {};
      const nextWindowPresets: Record<string, OfficeThemePresetId> = {};
      ((response.data || []) as Array<Record<string, unknown>>).forEach((row) => {
        const pageKeyRaw = String(row.page_key || "");
        const presetRaw = String(row.theme_preset || "industrial-night") as OfficeThemePresetId;
        const validPreset: OfficeThemePresetId = presetRaw === "custom" || Object.prototype.hasOwnProperty.call(OFFICE_THEME_PRESETS, presetRaw) ? presetRaw : "industrial-night";
        const baseTheme = validPreset === "custom" ? OFFICE_THEME_PRESETS["industrial-night"].theme : OFFICE_THEME_PRESETS[validPreset as Exclude<OfficeThemePresetId,"custom">].theme;
        const loadedTheme = ensureReadableOfficeTheme({ ...cloneOfficeTheme(baseTheme), ...((row.theme_json || {}) as Partial<OfficeThemeConfig>) });
        if (pageKeyRaw.startsWith(OFFICE_WINDOW_UI_PREFIX)) {
          const stateKey = pageKeyRaw.slice(OFFICE_WINDOW_UI_PREFIX.length);
          nextWindowThemes[stateKey] = loadedTheme;
          nextWindowPresets[stateKey] = validPreset;
          return;
        }
        const pageKey = pageKeyRaw as OfficePageKey;
        if (!Object.prototype.hasOwnProperty.call(nextThemes, pageKey)) return;
        nextThemes[pageKey] = loadedTheme;
        nextPresets[pageKey] = validPreset;
      });
      setOfficeThemePresetByPage(nextPresets);
      setOfficeThemeByPage(nextThemes);
      setOfficeWindowThemeByKey(nextWindowThemes);
      setOfficeWindowPresetByKey(nextWindowPresets);
    } catch (error) { console.warn("UI beállítások betöltési hiba:", error); }
  }

  async function saveOfficeUiPreference(pageKey: OfficePageKey = managementSection): Promise<void> {
    setOfficeThemeSaving(true);
    try { await persistOfficeUiPreference(pageKey, officeThemePresetByPage[pageKey], getOfficeTheme(pageKey), true); }
    finally { setOfficeThemeSaving(false); }
  }

  async function fetchDashboardOrderNumberSuggestions(rawValue: string): Promise<string[]> {
    if (!supabase) return [];

    const rawSearch = String(rawValue || "").trim();
    const normalizedSearch = normalizeDashboardOrderSearch(rawSearch);
    if (!normalizedSearch) return [];

    // Gyorskód/részleges gyorskód esetén a szerveren előszűrünk az év + hónap
    // részre, majd kliensoldalon a getDashboardQuickOrderCode alapján pontosítunk.
    // Pl. 07178 -> R26 07 ... 178.
    let serverPattern = `%${normalizedSearch}%`;
    if (/^\d{2,5}$/.test(normalizedSearch)) {
      serverPattern = `R26${normalizedSearch.slice(0, 2)}%`;
    }

    let response = await supabase
      .from("work_logs")
      .select("order_number, created_at")
      .ilike("order_number", serverPattern)
      .order("created_at", { ascending: false })
      .limit(2500);

    if (response.error) {
      response = await supabase
        .from("work_log")
        .select("order_number, created_at")
        .ilike("order_number", serverPattern)
        .order("created_at", { ascending: false })
        .limit(2500);
    }

    if (response.error) {
      console.warn("Rendelésszám-javaslatok betöltési hibája:", response.error);
      return [];
    }

    const selectedKeys = new Set(
      dashboardOrderFiltersRef.current.map(normalizeDashboardOrderSearch)
    );
    const seen = new Set<string>();
    const suggestions: string[] = [];

    for (const row of (response.data || []) as Array<{ order_number?: string | null }>) {
      const orderNumber = String(row.order_number || "").trim();
      if (!orderNumber) continue;

      // KIZÁRÓLAG order_number kerülhet a listába.
      if (!matchesDashboardOrderFilters(orderNumber, [rawSearch])) continue;

      const normalizedOrder = normalizeDashboardOrderSearch(orderNumber);
      if (!normalizedOrder || selectedKeys.has(normalizedOrder) || seen.has(normalizedOrder)) continue;

      seen.add(normalizedOrder);
      suggestions.push(orderNumber);

      if (suggestions.length >= 50) break;
    }

    return suggestions;
  }

  function addDashboardOrderFilter(rawValue = dashboardOrderInput): void {
    const value = String(rawValue || "").trim();
    if (!value) return;
    const normalized = normalizeDashboardOrderSearch(value);
    if (!normalized) return;
    const next = Array.from(new Map([...dashboardOrderFilters, value].map((item) => [normalizeDashboardOrderSearch(item), item])).values());
    dashboardOrderFiltersRef.current = [...next];
    setDashboardOrderFilters(next);
    setDashboardOrderInput("");
    setDashboardOrderSuggestions([]);
    setDashboardOrderSuggestionsOpen(false);
    void loadManagementDashboardView(dashboardFilterMode, dashboardDate, dashboardDateTo, next);
  }

  function removeDashboardOrderFilter(value: string): void {
    const normalized = normalizeDashboardOrderSearch(value);
    const next = dashboardOrderFilters.filter((item) => normalizeDashboardOrderSearch(item) !== normalized);
    dashboardOrderFiltersRef.current = [...next];
    setDashboardOrderFilters(next);
    void loadManagementDashboardView(dashboardFilterMode, dashboardDate, dashboardDateTo, next);
  }

  function clearDashboardSecondaryFilters(): void {
    setDashboardSelectedStation("all");
    setDashboardSelectedWorker("all");
    dashboardOrderFiltersRef.current = [];
    setDashboardOrderFilters([]);
    setDashboardOrderInput("");
    setDashboardOrderSuggestions([]);
    setDashboardOrderSuggestionsOpen(false);
    void loadManagementDashboardView(dashboardFilterMode, dashboardDate, dashboardDateTo, []);
  }


  function normalizeReportDeliveryDateKey(value: unknown): string {
    const raw = String(value ?? "").trim();
    if (!raw) return "";

    // Supabase date/timestamp vagy már tiszta YYYY-MM-DD.
    const candidate = raw.slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(candidate)) return "";

    const parsed = new Date(`${candidate}T00:00:00`);
    if (Number.isNaN(parsed.getTime())) return "";

    const [year, month, day] = candidate.split("-").map(Number);
    if (
      parsed.getFullYear() !== year
      || parsed.getMonth() + 1 !== month
      || parsed.getDate() !== day
    ) {
      return "";
    }

    return candidate;
  }

  function getSafeReportDeliveryTodayKey(now = new Date()): string {
    const candidate = Number.isNaN(now.getTime()) ? new Date() : now;
    return getLocalDateKey(candidate);
  }

  function mapReportDeliveryProfileRow(row: Record<string, unknown>): ReportDeliveryProfile {
    const recipientsRaw = row.recipients;
    const recipients = Array.isArray(recipientsRaw)
      ? recipientsRaw.map((value) => String(value || "").trim()).filter(Boolean)
      : String(recipientsRaw || "").split(/[;,\n]+/).map((value) => value.trim()).filter(Boolean);
    const blocksRaw = row.custom_blocks;
    const customBlocks = Array.isArray(blocksRaw)
      ? blocksRaw.map((value) => String(value) as ReportDeliveryBlock).filter((value) => REPORT_DELIVERY_BLOCK_OPTIONS.some((item) => item.id === value))
      : ["worker-analysis"] as ReportDeliveryBlock[];
    const statusRaw = String(row.last_send_status || "").toLowerCase();
    const inferredStatus: "never" | "success" | "error" = statusRaw === "success" || statusRaw === "error"
      ? statusRaw
      : String(row.last_send_error || "").trim()
        ? "error"
        : row.last_sent_at
          ? "success"
          : "never";
    return {
      ...DEFAULT_REPORT_DELIVERY_PROFILE,
      id: String(row.id || ""),
      name: String(row.name || "Automatikus riport"),
      recipients,
      stationFilter: String(row.station_filter || "all"),
      workerFilter: String(row.worker_filter || "all"),
      orderFilter: String(row.order_filter || ""),
      productTypeFilter: (["all", "Standard", "Plus", "Extra"].includes(String(row.product_type_filter || "all"))
        ? String(row.product_type_filter || "all")
        : "all") as ReportDeliveryProductType,
      reportType: (Object.prototype.hasOwnProperty.call(REPORT_DELIVERY_REPORT_TYPE_LABELS, String(row.report_type || "worker-analysis"))
        ? String(row.report_type || "worker-analysis")
        : "worker-analysis") as ReportDeliveryReportType,
      customBlocks: customBlocks.length ? customBlocks : ["worker-analysis"],
      frequency: (["daily", "weekly", "monthly"].includes(String(row.frequency || "monthly"))
        ? String(row.frequency || "monthly")
        : "monthly") as ReportDeliveryFrequency,
      periodScope: (String(row.period_scope || "previous") === "current" ? "current" : "previous") as ReportDeliveryPeriodScope,
      reportFilterMode: (
        ["today", "current-week", "current-month", "custom", "from-date-to-today"].includes(String(row.report_filter_mode || ""))
          ? String(row.report_filter_mode)
          : normalizeReportDeliveryDateKey(row.report_filter_start_date)
            ? "custom"
            : String(row.frequency || "monthly") === "daily"
              ? "today"
              : String(row.frequency || "monthly") === "weekly"
                ? "current-week"
                : "current-month"
      ) as ReportDeliveryDataRangeMode,
      reportFilterStartDate: normalizeReportDeliveryDateKey(row.report_filter_start_date),
      reportFilterEndDate: normalizeReportDeliveryDateKey(row.report_filter_end_date),
      sendTime: String(row.send_time || "06:00").slice(0, 5),
      scheduleStartDate: normalizeReportDeliveryDateKey(row.schedule_start_date),
      scheduleEndDate: normalizeReportDeliveryDateKey(row.schedule_end_date),
      weeklyDay: Math.min(7, Math.max(1, Number(row.weekly_day || 1))),
      monthlyDay: Math.min(28, Math.max(1, Number(row.monthly_day || 1))),
      active: Boolean(row.active),
      lastSentMarker: String(row.last_sent_marker || ""),
      lastSentAt: String(row.last_sent_at || ""),
      lastAttemptAt: String(row.last_attempt_at || ""),
      lastSendStatus: inferredStatus,
      lastSendError: String(row.last_send_error || ""),
      createdBy: String(row.created_by || ""),
      createdAt: String(row.created_at || ""),
      updatedAt: String(row.updated_at || ""),
    };
  }

  function mapReportDeliverySendLogRow(row: Record<string, unknown>): ReportDeliverySendLog {
    const recipientsRaw = row.recipients;
    return {
      id: String(row.id || ""),
      profileId: String(row.profile_id || ""),
      profileName: String(row.profile_name || ""),
      recipients: Array.isArray(recipientsRaw) ? recipientsRaw.map((value) => String(value || "")) : [],
      status: String(row.status || ""),
      isTest: Boolean(row.is_test),
      errorMessage: String(row.error_message || ""),
      attemptedAt: String(row.attempted_at || row.created_at || ""),
      completedAt: String(row.completed_at || ""),
      createdBy: String(row.created_by || ""),
    };
  }

  function parseReportDeliveryRecipients(value: string): string[] {
    return Array.from(new Set(
      String(value || "")
        .split(/[;,\n]+/)
        .map((item) => item.trim())
        .filter(Boolean)
    ));
  }

  function parseReportDeliveryOrderFilters(value: string): string[] {
    return Array.from(new Set(
      String(value || "")
        .split(/[;,\n]+/)
        .map((item) => item.trim())
        .filter(Boolean)
    ));
  }

  function cloneReportDeliveryProfile(profile: ReportDeliveryProfile): ReportDeliveryProfile {
    return { ...profile, recipients: [...profile.recipients], customBlocks: [...profile.customBlocks] };
  }

  function sortReportDeliveryProfiles(rows: ReportDeliveryProfile[]): ReportDeliveryProfile[] {
    return [...rows].sort((a, b) => {
      const aTime = a.createdAt ? new Date(a.createdAt).getTime() : Number(a.id || 0);
      const bTime = b.createdAt ? new Date(b.createdAt).getTime() : Number(b.id || 0);
      if (aTime !== bTime) return aTime - bTime;
      return Number(a.id || 0) - Number(b.id || 0);
    });
  }

  function setReportDeliveryProfileBusy(profileId: string, busy: boolean): void {
    setReportDeliveryBusyById((current) => ({ ...current, [profileId]: busy }));
  }

  function updateReportDeliveryDraft(profileId: string, patch: Partial<ReportDeliveryProfile>): void {
    setReportDeliveryDrafts((current) => {
      const existing = current[profileId] || reportDeliveryProfiles.find((item) => item.id === profileId);
      if (!existing) return current;
      return { ...current, [profileId]: { ...existing, ...patch } };
    });
  }

  function getReportDeliveryCardStyle(profileId: string): ReportDeliveryCardStyle {
    return reportDeliveryCardStyleByProfile[profileId] || cloneReportDeliveryCardStyle(DEFAULT_REPORT_DELIVERY_CARD_STYLE);
  }

  function queueReportDeliveryProfileStyleSave(profileId: string, style: ReportDeliveryCardStyle, preset: ReportDeliveryCardPresetId): void {
    const key = `report-profile-style:${profileId}`;
    const currentTimer = officeUiAutoSaveTimersRef.current[key];
    if (currentTimer) clearTimeout(currentTimer);
    officeUiAutoSaveTimersRef.current[key] = setTimeout(() => {
      delete officeUiAutoSaveTimersRef.current[key];
      void saveReportDeliveryProfileStyle(profileId, style, preset, false).catch((error) => console.warn("Riportprofil stílus automatikus mentési hiba:", error));
    }, 650);
  }

  function applyReportDeliveryCardPreset(profileId: string, presetId: Exclude<ReportDeliveryCardPresetId, "custom">): void {
    const style = cloneReportDeliveryCardStyle(REPORT_DELIVERY_CARD_PRESETS[presetId].style);
    setReportDeliveryCardPresetByProfile((current) => ({ ...current, [profileId]: presetId }));
    setReportDeliveryCardStyleByProfile((current) => ({ ...current, [profileId]: style }));
    queueReportDeliveryProfileStyleSave(profileId, style, presetId);
  }

  function updateReportDeliveryCardStyle(profileId: string, patch: Partial<ReportDeliveryCardStyle>): void {
    const nextStyle = { ...getReportDeliveryCardStyle(profileId), ...patch };
    setReportDeliveryCardPresetByProfile((current) => ({ ...current, [profileId]: "custom" }));
    setReportDeliveryCardStyleByProfile((current) => ({ ...current, [profileId]: nextStyle }));
    queueReportDeliveryProfileStyleSave(profileId, nextStyle, "custom");
  }

  async function loadReportDeliveryProfileStyles(profileIds: string[]): Promise<void> {
    if (!supabase || !activeWorker || !profileIds.length) return;
    const pageKeys = profileIds.map((id) => `${REPORT_DELIVERY_PROFILE_UI_PREFIX}${id}`);
    const defaultStyles: Record<string, ReportDeliveryCardStyle> = {};
    const defaultPresets: Record<string, ReportDeliveryCardPresetId> = {};
    profileIds.forEach((id) => {
      defaultStyles[id] = cloneReportDeliveryCardStyle(DEFAULT_REPORT_DELIVERY_CARD_STYLE);
      defaultPresets[id] = "industrial-night";
    });
    try {
      const response = await supabase
        .from("user_ui_preferences")
        .select("page_key, theme_preset, theme_json")
        .eq("worker_name", activeWorker["Teljes nev"])
        .in("page_key", pageKeys);
      if (response.error) {
        console.warn("Riportprofil megjelenési beállítások nem olvashatók:", response.error);
        setReportDeliveryCardStyleByProfile((current) => ({ ...defaultStyles, ...current }));
        setReportDeliveryCardPresetByProfile((current) => ({ ...defaultPresets, ...current }));
        return;
      }
      for (const row of (response.data || []) as Array<Record<string, unknown>>) {
        const pageKey = String(row.page_key || "");
        const profileId = pageKey.startsWith(REPORT_DELIVERY_PROFILE_UI_PREFIX) ? pageKey.slice(REPORT_DELIVERY_PROFILE_UI_PREFIX.length) : "";
        if (!profileId) continue;
        const presetRaw = String(row.theme_preset || "industrial-night") as ReportDeliveryCardPresetId;
        const validPreset = Object.prototype.hasOwnProperty.call(REPORT_DELIVERY_CARD_PRESETS, presetRaw) || presetRaw === "custom"
          ? presetRaw
          : "industrial-night";
        const baseStyle = validPreset === "custom"
          ? DEFAULT_REPORT_DELIVERY_CARD_STYLE
          : REPORT_DELIVERY_CARD_PRESETS[validPreset as Exclude<ReportDeliveryCardPresetId, "custom">].style;
        defaultPresets[profileId] = validPreset;
        defaultStyles[profileId] = {
          ...cloneReportDeliveryCardStyle(baseStyle),
          ...((row.theme_json || {}) as Partial<ReportDeliveryCardStyle>),
        };
      }
      setReportDeliveryCardStyleByProfile((current) => ({ ...current, ...defaultStyles }));
      setReportDeliveryCardPresetByProfile((current) => ({ ...current, ...defaultPresets }));
    } catch (error) {
      console.warn("Riportprofil megjelenési beállítás betöltési hiba:", error);
    }
  }

  async function saveReportDeliveryProfileStyle(profileId: string, styleOverride?: ReportDeliveryCardStyle, presetOverride?: ReportDeliveryCardPresetId, showMessage = true): Promise<void> {
    if (!supabase || !activeWorker || !profileId) return;
    const style = styleOverride || getReportDeliveryCardStyle(profileId);
    const preset = presetOverride || reportDeliveryCardPresetByProfile[profileId] || "industrial-night";
    const pageKey = `${REPORT_DELIVERY_PROFILE_UI_PREFIX}${profileId}`;
    const existingResponse = await supabase.from("user_ui_preferences").select("theme_preset, theme_json").eq("worker_name", activeWorker["Teljes nev"]).eq("page_key", pageKey).limit(1);
    if (existingResponse.error) throw existingResponse.error;
    const existing = (existingResponse.data || [])[0] as Record<string, unknown> | undefined;
    const response = await supabase.from("user_ui_preferences").upsert({
      worker_name: activeWorker["Teljes nev"], worker_id: activeWorker.id, page_key: pageKey,
      theme_preset: preset, theme_json: style, layout_json: {}, visible_fields_json: {},
      ...(existing ? { previous_theme_preset: String(existing.theme_preset || "industrial-night"), previous_theme_json: existing.theme_json || {} } : {}),
      updated_at: new Date().toISOString(),
    }, { onConflict: "worker_name,page_key" });
    if (response.error) throw response.error;
    if (showMessage) setMessage({ type:"success", text:`A(z) ${profileId}. profil megjelenése elmentve a felhasználódhoz.` });
  }

  async function restorePreviousReportDeliveryProfileStyle(profileId: string): Promise<void> {
    if (!supabase || !activeWorker || !profileId) return;
    const pageKey = `${REPORT_DELIVERY_PROFILE_UI_PREFIX}${profileId}`;
    const response = await supabase.from("user_ui_preferences").select("theme_preset, theme_json, previous_theme_preset, previous_theme_json").eq("worker_name", activeWorker["Teljes nev"]).eq("page_key", pageKey).limit(1);
    if (response.error) throw response.error;
    const row = (response.data || [])[0] as Record<string, unknown> | undefined;
    if (!row || !row.previous_theme_json || Object.keys((row.previous_theme_json || {}) as Record<string, unknown>).length === 0) {
      setMessage({ type:"info", text:"Ehhez a riportprofilhoz még nincs korábbi megjelenés." }); return;
    }
    const previousPresetRaw = String(row.previous_theme_preset || "custom") as ReportDeliveryCardPresetId;
    const previousPreset: ReportDeliveryCardPresetId = previousPresetRaw === "custom" || Object.prototype.hasOwnProperty.call(REPORT_DELIVERY_CARD_PRESETS, previousPresetRaw) ? previousPresetRaw : "custom";
    const previousStyle = { ...DEFAULT_REPORT_DELIVERY_CARD_STYLE, ...((row.previous_theme_json || {}) as Partial<ReportDeliveryCardStyle>) };
    const swap = await supabase.from("user_ui_preferences").update({ theme_preset:previousPreset, theme_json:previousStyle, previous_theme_preset:String(row.theme_preset || "custom"), previous_theme_json:row.theme_json || {}, updated_at:new Date().toISOString() }).eq("worker_name", activeWorker["Teljes nev"]).eq("page_key", pageKey);
    if (swap.error) throw swap.error;
    setReportDeliveryCardPresetByProfile((current)=>({...current,[profileId]:previousPreset}));
    setReportDeliveryCardStyleByProfile((current)=>({...current,[profileId]:previousStyle}));
    setMessage({ type:"success", text:"A riportprofil előző megjelenése visszaállítva." });
  }

  async function loadReportDeliverySendLogs(profileId: string): Promise<void> {
    if (!supabase || !profileId) return;
    try {
      const response = await supabase
        .from(REPORT_DELIVERY_SEND_LOGS_TABLE)
        .select("*")
        .eq("profile_id", Number(profileId))
        .order("attempted_at", { ascending: false })
        .limit(100);
      if (response.error) throw response.error;
      setReportDeliverySendLogsByProfile((current) => ({
        ...current,
        [profileId]: ((response.data || []) as Record<string, unknown>[]).map(mapReportDeliverySendLogRow),
      }));
    } catch (error) {
      setMessage({ type: "error", text: `Küldési napló betöltési hiba: ${normalizeError(error)}. Ha most telepítetted a fejlesztést, futtasd le a mellékelt Supabase SQL-t.` });
    }
  }

  async function writeReportDeliverySendLog(profile: ReportDeliveryProfile, params: { status: string; isTest: boolean; errorMessage?: string; attemptedAt: string; completedAt: string }): Promise<void> {
    if (!supabase || !profile.id) return;
    try {
      const response = await supabase.from(REPORT_DELIVERY_SEND_LOGS_TABLE).insert({
        profile_id: Number(profile.id),
        profile_name: profile.name,
        recipients: profile.recipients,
        report_type: profile.reportType,
        station_filter: profile.stationFilter,
        worker_filter: profile.workerFilter,
        order_filter: profile.orderFilter,
        product_type_filter: profile.productTypeFilter,
        frequency: profile.frequency,
        period_scope: profile.periodScope,
        status: params.status,
        is_test: params.isTest,
        error_message: params.errorMessage || "",
        attempted_at: params.attemptedAt,
        completed_at: params.completedAt,
        created_by: activeWorker?.["Teljes nev"] || profile.createdBy || "",
      });
      if (response.error) console.warn("Riportküldési napló mentési hiba:", response.error);
    } catch (error) {
      console.warn("Riportküldési napló mentési hiba:", error);
    }
  }

  async function loadReportDeliveryProfiles(): Promise<void> {
    if (!supabase) return;
    setReportDeliveryLoading(true);
    try {
      const response = await supabase
        .from(REPORT_DELIVERY_PROFILES_TABLE)
        .select("*")
        .order("created_at", { ascending: true });
      if (response.error) throw response.error;
      const rows = sortReportDeliveryProfiles(((response.data || []) as Record<string, unknown>[]).map(mapReportDeliveryProfileRow));
      setReportDeliveryProfiles(rows);
      const drafts: Record<string, ReportDeliveryProfile> = {};
      const recipientTexts: Record<string, string> = {};
      rows.forEach((profile) => {
        drafts[profile.id] = cloneReportDeliveryProfile(profile);
        recipientTexts[profile.id] = profile.recipients.join("; ");
      });
      setReportDeliveryDrafts(drafts);
      setReportDeliveryRecipientTextById(recipientTexts);
      setReportDeliveryProfilesLoaded(true);
      void loadReportDeliveryProfileStyles(rows.map((row) => row.id));
    } catch (error) {
      console.error("Riportküldési profilok betöltési hiba:", error);
      setMessage({ type: "error", text: `Riportprofilok betöltése sikertelen: ${normalizeError(error)}` });
    } finally {
      setReportDeliveryLoading(false);
    }
  }

  async function createNewReportDeliveryProfile(): Promise<void> {
    if (!supabase) throw new Error("Nincs Supabase kapcsolat.");
    const nextNumber = reportDeliveryProfiles.length + 1;
    const nowIso = new Date().toISOString();
    const payload = {
      name: "Új automatikus riport",
      recipients: [],
      station_filter: "all",
      worker_filter: "all",
      order_filter: "",
      product_type_filter: "all",
      report_type: "worker-analysis",
      custom_blocks: ["worker-analysis"],
      frequency: "monthly",
      period_scope: "previous",
      report_filter_mode: "current-month",
      report_filter_start_date: null,
      report_filter_end_date: null,
      send_time: "06:00",
      schedule_start_date: null,
      schedule_end_date: null,
      weekly_day: 1,
      monthly_day: 1,
      active: false,
      last_sent_marker: "",
      last_sent_at: null,
      last_send_error: "",
      created_by: activeWorker?.["Teljes nev"] || "",
      created_at: nowIso,
      updated_at: nowIso,
    };
    setReportDeliveryLoading(true);
    try {
      const response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).insert(payload).select("*").single();
      if (response.error) throw response.error;
      const profile = mapReportDeliveryProfileRow((response.data || {}) as Record<string, unknown>);
      setReportDeliveryProfiles((current) => sortReportDeliveryProfiles([...current, profile]));
      setReportDeliveryDrafts((current) => ({ ...current, [profile.id]: cloneReportDeliveryProfile(profile) }));
      setReportDeliveryRecipientTextById((current) => ({ ...current, [profile.id]: "" }));
      setReportDeliveryCardStyleByProfile((current) => ({ ...current, [profile.id]: cloneReportDeliveryCardStyle(DEFAULT_REPORT_DELIVERY_CARD_STYLE) }));
      setReportDeliveryCardPresetByProfile((current) => ({ ...current, [profile.id]: "industrial-night" }));
      setMessage({ type: "success", text: `${nextNumber}. riportprofil létrehozva. Állítsd be, majd mentsd el.` });
    } finally {
      setReportDeliveryLoading(false);
    }
  }

  function normalizeReportDeliveryFilterDates(profile: ReportDeliveryProfile): {
    mode: ReportDeliveryDataRangeMode;
    startDate: string | null;
    endDate: string | null;
  } {
    const mode = profile.reportFilterMode || "current-month";

    if (mode === "custom") {
      return {
        mode,
        startDate: normalizeReportDeliveryDateKey(profile.reportFilterStartDate) || null,
        endDate: normalizeReportDeliveryDateKey(profile.reportFilterEndDate) || null,
      };
    }

    if (mode === "from-date-to-today") {
      return {
        mode,
        startDate: normalizeReportDeliveryDateKey(profile.reportFilterStartDate) || null,
        endDate: null,
      };
    }

    return {
      mode,
      startDate: null,
      endDate: null,
    };
  }

  function buildReportDeliveryProfilePayload(profile: ReportDeliveryProfile, activeOverride?: boolean): Record<string, unknown> {
    const normalizedFilterDates = normalizeReportDeliveryFilterDates(profile);

    return {
      name: profile.name.trim() || "Automatikus riport",
      recipients: profile.recipients.map((value) => value.trim()).filter(Boolean),
      station_filter: profile.stationFilter || "all",
      worker_filter: profile.workerFilter || "all",
      order_filter: profile.orderFilter.trim(),
      product_type_filter: profile.productTypeFilter,
      report_type: profile.reportType,
      custom_blocks: profile.customBlocks,
      frequency: profile.frequency,
      period_scope: profile.periodScope,
      report_filter_mode: normalizedFilterDates.mode,
      report_filter_start_date: normalizedFilterDates.startDate,
      report_filter_end_date: normalizedFilterDates.endDate,
      send_time: profile.sendTime || "06:00",
      schedule_start_date: profile.scheduleStartDate || null,
      schedule_end_date: profile.scheduleEndDate || null,
      weekly_day: Math.min(7, Math.max(1, Number(profile.weeklyDay || 1))),
      monthly_day: Math.min(28, Math.max(1, Number(profile.monthlyDay || 1))),
      active: activeOverride === undefined ? profile.active : activeOverride,
      created_by: profile.createdBy || activeWorker?.["Teljes nev"] || "",
      updated_at: new Date().toISOString(),
    };
  }

  function validateReportDeliveryDataRange(profile: ReportDeliveryProfile): void {
    const startDate = normalizeReportDeliveryDateKey(profile.reportFilterStartDate);
    const endDate = normalizeReportDeliveryDateKey(profile.reportFilterEndDate);

    if (profile.reportFilterMode === "custom") {
      if (!startDate || !endDate) {
        throw new Error("Az Egyedi dátumtartománynál adj meg két érvényes dátumot.");
      }
      if (startDate > endDate) {
        throw new Error("A riport adatainak kezdő dátuma nem lehet későbbi a záró dátumnál.");
      }
    }

    if (profile.reportFilterMode === "from-date-to-today" && !startDate) {
      throw new Error("A Fix kezdő dátumtól → Mai napig módhoz adj meg egy érvényes kezdő dátumot.");
    }
  }

  async function saveReportDeliverySpecialTimeSettings(profile: ReportDeliveryProfile): Promise<void> {
    if (!supabase || !profile.id) throw new Error("Nincs menthető riportprofil.");

    validateReportDeliveryDataRange(profile);

    const normalized = normalizeReportDeliveryFilterDates(profile);
    setReportDeliveryProfileBusy(profile.id, true);

    try {
      const payload = {
        report_filter_mode: normalized.mode,
        report_filter_start_date: normalized.startDate,
        report_filter_end_date: normalized.endDate,
        updated_at: new Date().toISOString(),
      };

      const response = await supabase
        .from(REPORT_DELIVERY_PROFILES_TABLE)
        .update(payload)
        .eq("id", profile.id)
        .select("id, report_filter_mode, report_filter_start_date, report_filter_end_date, updated_at")
        .single();

      if (response.error) throw response.error;

      const savedMode = String(response.data?.report_filter_mode || normalized.mode) as ReportDeliveryDataRangeMode;
      const savedStart = normalizeReportDeliveryDateKey(response.data?.report_filter_start_date);
      const savedEnd = normalizeReportDeliveryDateKey(response.data?.report_filter_end_date);
      const savedUpdatedAt = String(response.data?.updated_at || new Date().toISOString());

      setReportDeliveryProfiles((current) =>
        current.map((item) =>
          item.id === profile.id
            ? {
                ...item,
                reportFilterMode: savedMode,
                reportFilterStartDate: savedStart,
                reportFilterEndDate: savedEnd,
                updatedAt: savedUpdatedAt,
              }
            : item
        )
      );

      setReportDeliveryDrafts((current) => ({
        ...current,
        [profile.id]: {
          ...(current[profile.id] || profile),
          reportFilterMode: savedMode,
          reportFilterStartDate: savedStart,
          reportFilterEndDate: savedEnd,
          updatedAt: savedUpdatedAt,
        },
      }));

      setReportDeliverySpecialTimeOpenById((current) => ({ ...current, [profile.id]: false }));
      setMessage({ type: "success", text: "A speciális riport-időbeállítások elmentve." });
    } finally {
      setReportDeliveryProfileBusy(profile.id, false);
    }
  }

  async function saveReportDeliveryProfile(profile: ReportDeliveryProfile, asCopy = false): Promise<void> {
    if (!supabase || !profile.id) throw new Error("Nincs menthető riportprofil.");
    const recipients = profile.recipients.map((value) => value.trim()).filter(Boolean);
    if (!profile.name.trim()) throw new Error("Adj nevet a riportprofilnak.");
    if (!recipients.length) throw new Error("Adj meg legalább egy email címet.");
    validateReportDeliveryDataRange(profile);
    if (profile.scheduleStartDate && profile.scheduleEndDate && profile.scheduleStartDate > profile.scheduleEndDate) {
      throw new Error("A riportküldés kezdő dátuma nem lehet későbbi a záró dátumnál.");
    }
    setReportDeliveryProfileBusy(profile.id, true);
    try {
      const payload = buildReportDeliveryProfilePayload({ ...profile, recipients });
      if (asCopy) {
        const copyPayload = {
          ...payload,
          name: `${profile.name.trim()} – másolat`,
          active: false,
          last_sent_marker: "",
          last_sent_at: null,
          last_send_error: "",
          created_at: new Date().toISOString(),
        };
        const response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).insert(copyPayload).select("*").single();
        if (response.error) throw response.error;
        const saved = mapReportDeliveryProfileRow((response.data || {}) as Record<string, unknown>);
        setReportDeliveryProfiles((current) => sortReportDeliveryProfiles([...current, saved]));
        setReportDeliveryDrafts((current) => ({ ...current, [saved.id]: cloneReportDeliveryProfile(saved) }));
        setReportDeliveryRecipientTextById((current) => ({ ...current, [saved.id]: saved.recipients.join("; ") }));
        const sourceStyle = getReportDeliveryCardStyle(profile.id);
        const sourcePreset = reportDeliveryCardPresetByProfile[profile.id] || "industrial-night";
        setReportDeliveryCardStyleByProfile((current) => ({ ...current, [saved.id]: cloneReportDeliveryCardStyle(sourceStyle) }));
        setReportDeliveryCardPresetByProfile((current) => ({ ...current, [saved.id]: sourcePreset }));
        try { await saveReportDeliveryProfileStyle(saved.id, sourceStyle, sourcePreset); } catch (error) { console.warn(error); }
        setMessage({ type: "success", text: "A riportprofil másolata elkészült és új sorszámot kapott." });
        return;
      }

      const response = await supabase
        .from(REPORT_DELIVERY_PROFILES_TABLE)
        .update(payload)
        .eq("id", profile.id)
        .select("*")
        .single();
      if (response.error) throw response.error;
      const saved = mapReportDeliveryProfileRow((response.data || {}) as Record<string, unknown>);
      setReportDeliveryProfiles((current) => sortReportDeliveryProfiles(current.map((item) => item.id === saved.id ? saved : item)));
      setReportDeliveryDrafts((current) => ({ ...current, [saved.id]: cloneReportDeliveryProfile(saved) }));
      setReportDeliveryRecipientTextById((current) => ({ ...current, [saved.id]: saved.recipients.join("; ") }));
      setMessage({ type: "success", text: `${profile.name} elmentve Supabase-ba.` });
    } finally {
      setReportDeliveryProfileBusy(profile.id, false);
    }
  }

  async function deleteReportDeliveryProfile(profile: ReportDeliveryProfile): Promise<void> {
    if (!supabase || !profile.id) return;
    if (typeof window !== "undefined" && !window.confirm(`Biztosan törlöd ezt a riportprofilt?\n\n${profile.name}`)) return;
    setReportDeliveryProfileBusy(profile.id, true);
    try {
      const response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).delete().eq("id", profile.id);
      if (response.error) throw response.error;
      if (activeWorker) {
        await supabase.from("user_ui_preferences").delete()
          .eq("worker_name", activeWorker["Teljes nev"])
          .eq("page_key", `${REPORT_DELIVERY_PROFILE_UI_PREFIX}${profile.id}`);
      }
      setReportDeliveryProfiles((current) => current.filter((item) => item.id !== profile.id));
      setReportDeliveryDrafts((current) => { const next = { ...current }; delete next[profile.id]; return next; });
      setReportDeliveryRecipientTextById((current) => { const next = { ...current }; delete next[profile.id]; return next; });
      setReportDeliveryCardStyleByProfile((current) => { const next = { ...current }; delete next[profile.id]; return next; });
      setReportDeliveryCardPresetByProfile((current) => { const next = { ...current }; delete next[profile.id]; return next; });
      setReportDeliverySendLogsByProfile((current) => { const next = { ...current }; delete next[profile.id]; return next; });
      setMessage({ type: "success", text: "A riportprofil törölve. A látható profilsorszámok automatikusan újraszámozódtak." });
    } finally {
      setReportDeliveryProfileBusy(profile.id, false);
    }
  }

  async function toggleReportDeliveryProfile(profile: ReportDeliveryProfile): Promise<void> {
    if (!supabase || !profile.id) return;
    const nextActive = !profile.active;
    if (nextActive && !profile.recipients.map((value) => value.trim()).filter(Boolean).length) {
      throw new Error("Aktiválás előtt adj meg legalább egy címzett email címet.");
    }
    if (nextActive) validateReportDeliveryDataRange(profile);
    if (nextActive && profile.scheduleStartDate && profile.scheduleEndDate && profile.scheduleStartDate > profile.scheduleEndDate) {
      throw new Error("A riportküldés kezdő dátuma nem lehet későbbi a záró dátumnál.");
    }
    setReportDeliveryProfileBusy(profile.id, true);
    try {
      const payload = buildReportDeliveryProfilePayload(profile, nextActive);
      const response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).update(payload).eq("id", profile.id).select("*").single();
      if (response.error) throw response.error;
      const saved = mapReportDeliveryProfileRow((response.data || {}) as Record<string, unknown>);
      setReportDeliveryProfiles((current) => sortReportDeliveryProfiles(current.map((item) => item.id === saved.id ? saved : item)));
      setReportDeliveryDrafts((current) => ({ ...current, [saved.id]: cloneReportDeliveryProfile(saved) }));
      setReportDeliveryRecipientTextById((current) => ({ ...current, [saved.id]: saved.recipients.join("; ") }));
      setMessage({ type: "success", text: nextActive ? `${profile.name} automatikus küldése AKTÍV.` : `${profile.name} automatikus küldése KIKAPCSOLVA.` });
    } finally {
      setReportDeliveryProfileBusy(profile.id, false);
    }
  }

  async function stopAllReportDeliveryProfiles(): Promise<void> {
    if (!supabase) return;
    const activeCount = reportDeliveryProfiles.filter((profile) => profile.active).length;
    if (!activeCount) {
      setMessage({ type: "info", text: "Jelenleg nincs aktív automatikus riportprofil." });
      return;
    }
    if (typeof window !== "undefined" && !window.confirm(`Biztosan leállítod az összes automatikus riportküldést?\n\nAktív profilok: ${activeCount}`)) return;
    setReportDeliveryLoading(true);
    try {
      const response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).update({ active: false, updated_at: new Date().toISOString() }).eq("active", true);
      if (response.error) throw response.error;
      setReportDeliveryProfiles((current) => current.map((profile) => ({ ...profile, active: false })));
      setReportDeliveryDrafts((current) => {
        const next = { ...current };
        Object.keys(next).forEach((id) => { next[id] = { ...next[id], active: false }; });
        return next;
      });
      setMessage({ type: "success", text: "MINDEN automatikus riportküldés leállítva." });
    } finally {
      setReportDeliveryLoading(false);
    }
  }

  function getReportDeliveryScheduleStart(profile: ReportDeliveryProfile): Date | null {
    if (!profile.scheduleStartDate) return null;
    const value = new Date(`${profile.scheduleStartDate}T00:00:00`);
    return Number.isNaN(value.getTime()) ? null : value;
  }

  function getReportDeliveryScheduleEnd(profile: ReportDeliveryProfile): Date | null {
    if (!profile.scheduleEndDate) return null;
    const value = new Date(`${profile.scheduleEndDate}T23:59:59.999`);
    return Number.isNaN(value.getTime()) ? null : value;
  }

  function isInsideReportDeliveryScheduleWindow(profile: ReportDeliveryProfile, now = new Date()): boolean {
    const start = getReportDeliveryScheduleStart(profile);
    const end = getReportDeliveryScheduleEnd(profile);
    if (start && now.getTime() < start.getTime()) return false;
    if (end && now.getTime() > end.getTime()) return false;
    return true;
  }

  function getNextReportDeliveryRun(profile: ReportDeliveryProfile, now = new Date()): Date | null {
    if (!profile.active || !profile.sendTime) return null;

    const scheduleStart = getReportDeliveryScheduleStart(profile);
    const scheduleEnd = getReportDeliveryScheduleEnd(profile);
    if (scheduleEnd && now.getTime() > scheduleEnd.getTime()) return null;

    // Ha az érvényességi időszak még nem kezdődött el, onnan számoljuk
    // az első ütemezett futást.
    const calculationBase = scheduleStart && now.getTime() < scheduleStart.getTime()
      ? new Date(scheduleStart)
      : new Date(now);

    const [hourText, minuteText] = profile.sendTime.split(":");
    const hour = Math.min(23, Math.max(0, Number(hourText || 0)));
    const minute = Math.min(59, Math.max(0, Number(minuteText || 0)));
    const candidate = new Date(calculationBase);
    candidate.setSeconds(0, 0);
    candidate.setHours(hour, minute, 0, 0);

    if (profile.frequency === "daily") {
      if (candidate.getTime() <= calculationBase.getTime()) candidate.setDate(candidate.getDate() + 1);
    } else if (profile.frequency === "weekly") {
      const jsTargetDay = profile.weeklyDay === 7 ? 0 : profile.weeklyDay;
      let delta = (jsTargetDay - candidate.getDay() + 7) % 7;
      if (delta === 0 && candidate.getTime() <= calculationBase.getTime()) delta = 7;
      candidate.setDate(candidate.getDate() + delta);
    } else {
      candidate.setDate(Math.min(28, Math.max(1, profile.monthlyDay || 1)));
      if (candidate.getTime() <= calculationBase.getTime()) {
        candidate.setMonth(
          candidate.getMonth() + 1,
          Math.min(28, Math.max(1, profile.monthlyDay || 1))
        );
      }
    }

    if (scheduleStart && candidate.getTime() < scheduleStart.getTime()) {
      candidate.setTime(scheduleStart.getTime());
      candidate.setHours(hour, minute, 0, 0);
    }

    if (scheduleEnd && candidate.getTime() > scheduleEnd.getTime()) return null;
    return candidate;
  }

  function getReportDeliveryProfileStatus(profile: ReportDeliveryProfile): { label: string; color: string } {
    if (reportDeliverySendingById[profile.id]) return { label: "KÜLDÉS FOLYAMATBAN", color: "#38bdf8" };
    if (!profile.active) return { label: "KIKAPCSOLVA", color: "#94a3b8" };
    if (profile.lastSendError || profile.lastSendStatus === "error") return { label: "HIBÁS", color: "#ef4444" };
    return { label: "AKTÍV", color: "#22c55e" };
  }

  function getReportDeliveryProfileRange(profile: ReportDeliveryProfile, now = new Date()): { startIso: string; endIso: string; label: string } {
    const safeNow = Number.isNaN(now.getTime()) ? new Date() : now;
    const todayKey = getSafeReportDeliveryTodayKey(safeNow);
    const mode = profile.reportFilterMode || "current-month";

    let startKey = todayKey;
    let endKey = todayKey;

    if (mode === "current-week") {
      startKey = getLocalDateKey(getStartOfWeek(safeNow));
    } else if (mode === "current-month") {
      startKey = getLocalDateKey(new Date(safeNow.getFullYear(), safeNow.getMonth(), 1));
    } else if (mode === "from-date-to-today") {
      startKey = normalizeReportDeliveryDateKey(profile.reportFilterStartDate) || todayKey;
    } else if (mode === "custom") {
      const customStart = normalizeReportDeliveryDateKey(profile.reportFilterStartDate);
      const customEnd = normalizeReportDeliveryDateKey(profile.reportFilterEndDate);

      // Régi vagy hibásan eltárolt dátum SOHA nem döntheti össze a riport oldalt.
      // Ha valamelyik hibás, biztonságosan a mai napra esünk vissza,
      // a felhasználó pedig a Speciális időbeállításokban újra elmentheti.
      startKey = customStart || todayKey;
      endKey = customEnd || customStart || todayKey;
    }

    if (startKey > endKey) {
      const temp = startKey;
      startKey = endKey;
      endKey = temp;
    }

    try {
      return getDashboardDateRange("custom", startKey, endKey);
    } catch (error) {
      console.warn("Hibás riport dátumtartomány javítva a mai napra:", error);
      return getDashboardDateRange("custom", todayKey, todayKey);
    }
  }

  function getReportDeliveryDataRangeModeLabel(mode: ReportDeliveryDataRangeMode): string {
    if (mode === "today") return "Napi – mai nap";
    if (mode === "current-week") return "Heti – hétfőtől mai napig";
    if (mode === "current-month") return "Havi – hónap 1-től mai napig";
    if (mode === "from-date-to-today") return "Fix kezdő dátumtól → mai napig";
    return "Egyedi dátumtartomány";
  }

  function getReportDeliveryDataRangeSummary(profile: ReportDeliveryProfile, now = new Date()): string {
    try {
      const range = getReportDeliveryProfileRange(profile, now);
      const start = normalizeReportDeliveryDateKey(range.startIso) || getSafeReportDeliveryTodayKey(now);
      const inclusiveEndMs = new Date(range.endIso).getTime() - 1;
      const inclusiveEnd = new Date(inclusiveEndMs);
      const end = Number.isNaN(inclusiveEnd.getTime())
        ? start
        : getLocalDateKey(inclusiveEnd);

      return `${getReportDeliveryDataRangeModeLabel(profile.reportFilterMode || "current-month")} · ${start} → ${end}`;
    } catch (error) {
      console.warn("Riport időszak összefoglaló hiba:", error);
      return `${getReportDeliveryDataRangeModeLabel(profile.reportFilterMode || "current-month")} · dátum újrabeállítása szükséges`;
    }
  }

  function getReportDeliveryScheduleMarker(profile: ReportDeliveryProfile, now = new Date()): string {
    const dateKey = getLocalDateKey(now);
    const range = getReportDeliveryProfileRange(profile, now);
    return `${profile.frequency}|${dateKey}|${profile.sendTime}|${range.startIso.slice(0, 10)}|${range.endIso.slice(0, 10)}`;
  }

  function isReportDeliveryProfileDue(profile: ReportDeliveryProfile, now = new Date()): boolean {
    if (!profile.active || !profile.sendTime || !profile.recipients.length) return false;

    // A naptár csak az AUTOMATIKUS küldés érvényességét korlátozza.
    // A riportált adatok napi/heti/havi időszaklogikája változatlan.
    if (!isInsideReportDeliveryScheduleWindow(profile, now)) return false;

    const weekday = now.getDay() === 0 ? 7 : now.getDay();
    if (profile.frequency === "weekly" && weekday !== profile.weeklyDay) return false;
    if (profile.frequency === "monthly" && now.getDate() !== profile.monthlyDay) return false;
    const currentTime = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
    const scheduledTime = profile.sendTime.slice(0, 5);

    // NINCS utólagos / belépéskori pótlás.
    // 08:00-s beállítás kizárólag 08:00 percében küldhet.
    // Ha az alkalmazás 08:01-kor nyílik meg, a 08:00-s riport már nem megy ki.
    if (currentTime !== scheduledTime) return false;

    return profile.lastSentMarker !== getReportDeliveryScheduleMarker(profile, now);
  }

  function filterReportDeliveryLogs(sourceData: DashboardData, profile: ReportDeliveryProfile): WorkLogRow[] {
    return sourceData.logs.filter((log) => {
      const station = resolveLogStation(log, workers);
      const workerName = getDashboardLogWorkerName(log);
      return (profile.stationFilter === "all" || normalizeLooseText(station) === normalizeLooseText(profile.stationFilter))
        && (profile.workerFilter === "all" || normalizeLooseText(workerName) === normalizeLooseText(profile.workerFilter));
    });
  }

  async function createGenericReportDeliveryPdfBlob(
    profile: ReportDeliveryProfile,
    sourceData: DashboardData,
    range: { startIso: string; endIso: string; label: string }
  ): Promise<Blob> {
    const [jspdf, logoDataUrl] = await Promise.all([waitForJsPdf(), loadDashboardPdfCompanyLogo()]);
    const logoSize = await getPdfImageNaturalSize(logoDataUrl);
    const doc = new jspdf.jsPDF({ orientation: "portrait", unit: "pt", format: "a4" });
    const pdf = doc as any;
    registerPdfUnicodeFonts(doc);

    const pageWidth = 595.28;
    const pageHeight = 841.89;
    const marginX = 22;
    const contentWidth = pageWidth - marginX * 2;
    const footerY = pageHeight - 25;
    const ink = [39, 42, 47] as const;
    const charcoal = [57, 61, 67] as const;
    const mid = [98, 103, 110] as const;
    const pale = [247, 247, 247] as const;
    const light = [235, 236, 238] as const;
    const border = [195, 198, 202] as const;
    const generatedAt = formatDateTime(new Date());
    const title = REPORT_DELIVERY_REPORT_TYPE_LABELS[profile.reportType];
    const stationLabel = profile.stationFilter === "all" ? "Összes munkaállomás" : profile.stationFilter;
    const workerLabel = profile.workerFilter === "all" ? "Összes dolgozó" : profile.workerFilter;
    const orderLabel = profile.orderFilter.trim() || "Összes rendelés";

    const fitLogo = (maxWidth: number, maxHeight: number): { width: number; height: number } => {
      const ratio = logoSize.width / Math.max(1, logoSize.height);
      let width = maxWidth;
      let height = width / ratio;
      if (height > maxHeight) {
        height = maxHeight;
        width = height * ratio;
      }
      return { width, height };
    };

    const drawLogoAt = (x: number, y: number, maxWidth = 112, maxHeight = 50): void => {
      const fitted = fitLogo(maxWidth, maxHeight);
      const drawY = y + Math.max(0, (maxHeight - fitted.height) / 2);
      try {
        pdf.addImage(logoDataUrl, "PNG", x, drawY, fitted.width, fitted.height, undefined, "FAST");
      } catch {
        try { pdf.addImage(logoDataUrl, x, drawY, fitted.width, fitted.height); } catch { /* no-op */ }
      }
    };

    const drawMetaIcon = (type: "calendar" | "filter" | "clock", x: number, y: number): void => {
      doc.setDrawColor(...charcoal);
      doc.setLineWidth(1);
      if (type === "calendar") {
        pdf.roundedRect(x, y, 12, 11, 1.5, 1.5, "S");
        doc.line(x + 2, y + 3.5, x + 10, y + 3.5);
        doc.line(x + 3, y - 1, x + 3, y + 2);
        doc.line(x + 9, y - 1, x + 9, y + 2);
      } else if (type === "clock") {
        pdf.circle(x + 6, y + 5.5, 5.5, "S");
        doc.line(x + 6, y + 5.5, x + 6, y + 2);
        doc.line(x + 6, y + 5.5, x + 9, y + 7);
      } else {
        doc.line(x, y, x + 12, y);
        doc.line(x, y, x + 4.5, y + 5);
        doc.line(x + 12, y, x + 7.5, y + 5);
        doc.line(x + 4.5, y + 5, x + 4.5, y + 10);
        doc.line(x + 7.5, y + 5, x + 7.5, y + 10);
        doc.line(x + 4.5, y + 10, x + 7.5, y + 8.5);
      }
    };

    const drawHeader = (compact = false): number => {
      if (compact) {
        doc.setFillColor(255, 255, 255);
        doc.rect(0, 0, pageWidth, 78, "F");
        drawLogoAt(marginX, 13, 80, 34);
        doc.setDrawColor(...border);
        doc.line(118, 13, 118, 57);
        doc.setFont(PDF_FONT_FAMILY, "bold");
        doc.setFontSize(10.5);
        doc.setTextColor(...ink);
        doc.text(title.toUpperCase(), 132, 31, { maxWidth: 280 });
        doc.setFont(PDF_FONT_FAMILY, "normal");
        doc.setFontSize(6.5);
        doc.setTextColor(...mid);
        doc.text(range.label, 132, 46, { maxWidth: 280 });
        doc.setFillColor(...charcoal);
        doc.rect(marginX, 62, contentWidth, 20, "F");
        doc.setFont(PDF_FONT_FAMILY, "bold");
        doc.setFontSize(7.2);
        doc.setTextColor(255, 255, 255);
        doc.text("RÉSZLETES RIPORT", marginX + 10, 75);
        return 96;
      }

      doc.setFillColor(255, 255, 255);
      doc.rect(0, 0, pageWidth, 153, "F");
      drawLogoAt(marginX + 2, 24, 118, 54);
      doc.setDrawColor(...border);
      doc.setLineWidth(0.7);
      doc.line(160, 18, 160, 104);
      doc.line(430, 18, 430, 104);

      doc.setFont(PDF_FONT_FAMILY, "bold");
      doc.setFontSize(15.5);
      doc.setTextColor(...ink);
      const titleLines = doc.splitTextToSize(title.toUpperCase(), 246).slice(0, 2);
      doc.text(titleLines, 178, 37);
      const titleBottom = 37 + Math.max(0, titleLines.length - 1) * 17;
      doc.setFont(PDF_FONT_FAMILY, "normal");
      doc.setFontSize(8.2);
      doc.setTextColor(...mid);
      doc.text(profile.name.trim() || "Automatikus termelési riport", 178, titleBottom + 18, { maxWidth: 242 });

      const metaX = 446;
      const metaTextX = 466;
      const drawMetaRow = (icon: "calendar" | "filter" | "clock", label: string, value: string, top: number, maxLines = 2): void => {
        drawMetaIcon(icon, metaX, top + 2);
        doc.setFont(PDF_FONT_FAMILY, "bold");
        doc.setFontSize(6.3);
        doc.setTextColor(...ink);
        doc.text(label.toUpperCase(), metaTextX, top + 6);
        doc.setFont(PDF_FONT_FAMILY, "normal");
        doc.setFontSize(6.1);
        doc.setTextColor(...ink);
        const lines = doc.splitTextToSize(value, 103).slice(0, maxLines);
        doc.text(lines, metaTextX, top + 16);
        doc.setDrawColor(218, 219, 221);
        doc.line(metaX, top + 29, pageWidth - marginX, top + 29);
      };
      drawMetaRow("calendar", "Időszak", range.label, 21, 2);
      drawMetaRow("filter", "Szűrés", `${stationLabel} • ${workerLabel} • ${orderLabel}`, 51, 3);
      drawMetaRow("clock", "Generálva", generatedAt, 83, 2);

      doc.setFillColor(...charcoal);
      doc.rect(marginX, 119, contentWidth, 28, "F");
      doc.setFont(PDF_FONT_FAMILY, "bold");
      doc.setFontSize(9.5);
      doc.setTextColor(255, 255, 255);
      doc.text("ÁTTEKINTÉS", marginX + 11, 137);
      doc.setDrawColor(210, 210, 210);
      doc.line(marginX + 94, 126, marginX + 94, 141);
      doc.setFont(PDF_FONT_FAMILY, "normal");
      doc.setFontSize(6.7);
      doc.text("A mentett profil szűrése alapján automatikusan generált termelési riport.", marginX + 108, 137, { maxWidth: contentWidth - 120 });
      return 166;
    };

    let y = drawHeader(false);
    const visibleLogs = filterReportDeliveryLogs(sourceData, profile);
    const completedLogs = visibleLogs.filter((log) => String(log.action || "").toUpperCase() === "END" || Boolean(log.end_time || log.end_timestamp));
    const planRows = await loadDashboardPdfPlanRows(completedLogs.map((log) => String(log.order_number || "")).filter(Boolean));
    let analyses = buildDashboardPdfWorkerAnalyses(visibleLogs, planRows, profile.stationFilter, profile.workerFilter, sourceData);
    if (profile.productTypeFilter !== "all") {
      analyses = analyses.map((analysis) => {
        const completedOrders = analysis.completedOrders.filter((row) => row.productType === profile.productTypeFilter);
        const typeCounts: Record<string, number> = { Standard: 0, Plus: 0, Extra: 0, Egyéb: 0 };
        completedOrders.forEach((row) => {
          if (row.productType === "Standard" || row.productType === "Plus" || row.productType === "Extra") typeCounts[row.productType] += 1;
          else typeCounts.Egyéb += 1;
        });
        return { ...analysis, completedOrders, typeCounts };
      });
    }

    const ensureSpace = (needed = 100): void => {
      if (y + needed <= footerY - 10) return;
      pdf.addPage("a4", "portrait");
      y = drawHeader(true);
    };

    const drawSectionBand = (heading: string): void => {
      ensureSpace(42);
      doc.setFillColor(...charcoal);
      doc.rect(marginX, y, contentWidth, 25, "F");
      doc.setFont(PDF_FONT_FAMILY, "bold");
      doc.setFontSize(8.5);
      doc.setTextColor(255, 255, 255);
      doc.text(heading.toUpperCase(), marginX + 10, y + 16);
      y += 34;
    };

    const addSection = (heading: string, head: string[][], body: Array<Array<string | number>>): void => {
      ensureSpace(115);
      drawSectionBand(heading);
      pdf.autoTable({
        startY: y,
        head,
        body: body.length ? body : [["Nincs adat", ...Array(Math.max(0, head[0].length - 1)).fill("-")]],
        theme: "grid",
        margin: { left: marginX, right: marginX, top: 96, bottom: 45 },
        styles: {
          font: PDF_FONT_FAMILY,
          fontSize: 6.9,
          cellPadding: 4.2,
          overflow: "linebreak",
          textColor: ink,
          lineColor: border,
          lineWidth: 0.35,
        },
        headStyles: {
          font: PDF_FONT_FAMILY,
          fontStyle: "bold",
          fillColor: [76, 79, 84],
          textColor: [255, 255, 255],
          lineColor: [160, 163, 168],
          lineWidth: 0.35,
        },
        alternateRowStyles: { fillColor: pale },
        didDrawPage: (data: any) => {
          if (Number(data?.pageNumber || 1) <= 1) return;
          drawHeader(true);
        },
      });
      y = Number(pdf.lastAutoTable?.finalY || y + 70) + 18;
    };

    const addWorkerComparison = (): void => {
      const ranking = [...analyses].sort((a, b) => (b.performance.efficiencyPct ?? -1) - (a.performance.efficiencyPct ?? -1));
      ensureSpace(160);
      drawSectionBand("Termelékenységi rangsor");
      const maxPct = Math.max(100, ...ranking.map((row) => row.performance.efficiencyPct || 0));
      ranking.slice(0, 12).forEach((row, index) => {
        ensureSpace(24);
        const pct = row.performance.efficiencyPct || 0;
        doc.setFont(PDF_FONT_FAMILY, "bold");
        doc.setFontSize(6.8);
        doc.setTextColor(...ink);
        doc.text(`${index + 1}. ${row.workerName}`, marginX, y + 8, { maxWidth: 130 });
        doc.setFillColor(232, 233, 235);
        pdf.roundedRect(marginX + 138, y, 320, 10, 3, 3, "F");
        if (pct > 0) {
          const shade = index === 0 ? 54 : index < 3 ? 90 : 125;
          doc.setFillColor(shade, shade, shade);
          pdf.roundedRect(marginX + 138, y, Math.max(4, Math.min(320, pct / maxPct * 320)), 10, 3, 3, "F");
        }
        doc.setFont(PDF_FONT_FAMILY, "bold");
        doc.setFontSize(6.8);
        doc.setTextColor(...ink);
        doc.text(`${formatDashboardEfficiencyPct(pct)}%`, pageWidth - marginX, y + 8, { align: "right" });
        y += 20;
      });
      y += 8;
      addSection(
        "Összehasonlító ranglista",
        [["#", "Dolgozó", "Hatékonyság", "Ledolgozott", "Befejezett", "Standard", "Plus", "Extra"]],
        ranking.map((row, index) => [
          index + 1,
          row.workerName,
          row.performance.efficiencyPct === null ? "-" : `${formatDashboardEfficiencyPct(row.performance.efficiencyPct)}%`,
          row.performance.totalDurationLabel,
          row.completedOrders.length,
          row.typeCounts.Standard || 0,
          row.typeCounts.Plus || 0,
          row.typeCounts.Extra || 0,
        ])
      );
    };

    const addAtvetelReport = async (): Promise<void> => {
      let rows: Array<Record<string, unknown>> = [];

      if (supabase) {
        const response = await supabase
          .from(ATVETEL_CURRENT_TABLE)
          .select("order_number, beepitesi_datum, production_status, folyamatban, atvette, megjegyzes, lezart, lezart_at, lezarta_worker_id, lezarta_worker_name")
          .eq("lezart", true)
          .gte("lezart_at", range.startIso)
          .lt("lezart_at", range.endIso)
          .order("lezart_at", { ascending: true })
          .limit(5000);

        if (response.error) throw response.error;
        rows = (response.data || []) as Array<Record<string, unknown>>;
      }

      const orderFilters = parseReportDeliveryOrderFilters(profile.orderFilter);

      const filteredRows = rows.filter((row) => {
        const orderNumber = String(row.order_number || "").trim();
        if (!orderNumber) return false;

        if (
          orderFilters.length > 0
          && !matchesDashboardOrderFilters(orderNumber, orderFilters)
        ) {
          return false;
        }

        if (
          profile.workerFilter !== "all"
          && normalizeLooseText(String(row.lezarta_worker_name || ""))
            !== normalizeLooseText(profile.workerFilter)
        ) {
          return false;
        }

        return true;
      });

      const monthCounts = new Map<string, number>();
      filteredRows.forEach((row) => {
        const closedAt = String(row.lezart_at || "");
        const monthKey = closedAt.slice(0, 7);
        if (!/^\d{4}-\d{2}$/.test(monthKey)) return;
        monthCounts.set(monthKey, (monthCounts.get(monthKey) || 0) + 1);
      });

      const monthlyRows = Array.from(monthCounts.entries())
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([month, count]) => [month, count]);

      addSection(
        "Átvétel – havi lezárások",
        [["Hónap", "Lezárt rendelések száma"]],
        monthlyRows
      );

      addSection(
        "Átvétel – lezárt rendelések részletei",
        [["Rendelés", "Beépítési dátum", "Lezárás időpontja", "Lezáró", "Folyamatban", "Átvette", "Megjegyzés"]],
        filteredRows.map((row) => [
          String(row.order_number || "-"),
          String(row.beepitesi_datum || "-"),
          row.lezart_at ? formatDateTime(String(row.lezart_at)) : "-",
          String(row.lezarta_worker_name || "-"),
          Boolean(row.folyamatban) ? "Igen" : "Nem",
          Boolean(row.atvette) ? "Igen" : "Nem",
          String(row.megjegyzes || "-"),
        ])
      );
    };

    const addBlock = async (blockId: ReportDeliveryBlock): Promise<void> => {
      if (blockId === "worker-analysis") {
        addSection(
          "Dolgozói időszaki összesítő",
          [["Dolgozó", "Hatékonyság", "Ledolgozott", "Keret", "Rendelés", "Standard", "Plus", "Extra"]],
          analyses.map((row) => [
            row.workerName,
            row.performance.efficiencyPct === null ? "-" : `${formatDashboardEfficiencyPct(row.performance.efficiencyPct)}%`,
            row.performance.totalDurationLabel,
            formatReportMinutes(row.performance.accountedMinutes),
            row.completedOrders.length,
            row.typeCounts.Standard || 0,
            row.typeCounts.Plus || 0,
            row.typeCounts.Extra || 0,
          ])
        );
      } else if (blockId === "worker-comparison") {
        addWorkerComparison();
      } else if (blockId === "reproduction") {
        const rows = completedLogs.filter((log) => Boolean(log.ujragyartas)).map((log) => [
          log.order_number || "-",
          resolveLogStation(log, workers),
          getDashboardLogWorkerName(log),
          formatDateTime(getDashboardLogEndAt(log) || getDashboardLogEventAt(log)),
          String(log.ujragyartas_sorszam || "-"),
        ]);
        addSection("Újragyártási sorok", [["Rendelés", "Munkaállomás", "Dolgozó", "Befejezés", "Újragyártás #"]], rows);
      } else if (blockId === "scrap-replacement") {
        let rows: Array<Array<string | number>> = visibleLogs.filter((log) => Boolean(log.selejt_potlas)).map((log) => [
          log.order_number || "-", resolveLogStation(log, workers), getDashboardLogWorkerName(log),
          formatDateTime(getDashboardLogEventAt(log)), getNoteBeforeContext(log.note) || "-",
        ]);
        try {
          if (supabase) {
            const response = await supabase.from("asztalos_selejt_potlas").select("*")
              .gte("reported_at", range.startIso).lt("reported_at", range.endIso).order("reported_at", { ascending: false }).limit(2000);
            if (!response.error && response.data?.length) {
              rows = (response.data as Record<string, unknown>[]).map((row) => [
                String(row.sorszam || row.order_number || "-"),
                String(row.selejt_forras_munkaallomas || row.source_station || "-"),
                String(row.end_worker_name || row.worker_name || "-"),
                row.completed_at ? formatDateTime(String(row.completed_at)) : row.reported_at ? formatDateTime(String(row.reported_at)) : "-",
                String(row.megjegyzes || row.note || "-"),
              ]);
            }
          }
        } catch { /* fallback to work_logs */ }
        addSection("Selejtpótlási riport", [["Rendelés", "Forrás", "Dolgozó", "Időpont", "Megjegyzés"]], rows);
      } else if (blockId === "station-performance" || blockId === "plan-vs-completed") {
        const stationRows = sourceData.stationEfficiencyRows.filter((row) =>
          profile.stationFilter === "all" || normalizeLooseText(row.stationName) === normalizeLooseText(profile.stationFilter)
        );
        addSection(
          blockId === "station-performance" ? "Munkaállomás teljesítmény" : "Termelési terv vs. elkészült",
          [["Munkaállomás", "Tervezett", "Elkészült", "Hátralévő", "Teljesítés"]],
          stationRows.map((row) => [
            row.stationName,
            row.plannedItems,
            row.completedItems,
            Math.max(0, row.plannedItems - row.completedItems),
            row.efficiencyPct === null ? "-" : `${row.efficiencyPct}%`,
          ])
        );
      } else if (blockId === "closed-orders") {
        const rows = analyses.flatMap((analysis) => analysis.completedOrders.map((row) => [
          row.orderNumber,
          row.productType,
          row.stationName,
          analysis.workerName,
          row.completedAt ? formatDateTime(row.completedAt) : "-",
          row.elapsedLabel,
        ]));
        addSection("Lezárt rendelések", [["Rendelés", "Típus", "Munkaállomás", "Dolgozó", "Befejezés", "Eltelt"]], rows);
      }
    };

    if (profile.reportType === "custom") {
      for (const blockId of profile.customBlocks) await addBlock(blockId);
    } else if (profile.reportType === "atvetel") {
      await addAtvetelReport();
    } else {
      await addBlock(profile.reportType as ReportDeliveryBlock);
    }

    const pageCount = pdf.getNumberOfPages();
    for (let pageNumber = 1; pageNumber <= pageCount; pageNumber += 1) {
      pdf.setPage(pageNumber);
      doc.setDrawColor(...border);
      doc.setLineWidth(0.6);
      doc.line(marginX, footerY - 6, pageWidth - marginX, footerY - 6);
      doc.setFont(PDF_FONT_FAMILY, "normal");
      doc.setFontSize(6.3);
      doc.setTextColor(...mid);
      doc.text("NÍVÓ • Automatikus termelési riport", marginX, footerY + 7);
      doc.text(`Generálva: ${generatedAt}`, pageWidth / 2, footerY + 7, { align: "center" });
      doc.text(`Oldal ${pageNumber} / ${pageCount}`, pageWidth - marginX, footerY + 7, { align: "right" });
    }

    return doc.output("blob");
  }


  async function createReportDeliveryProfilePdfBlob(profile: ReportDeliveryProfile): Promise<Blob> {
    const range = getReportDeliveryProfileRange(profile);
    const sourceData = await fetchDashboardData(range, parseReportDeliveryOrderFilters(profile.orderFilter));
    if (profile.reportType === "worker-analysis") {
      return await createProfessionalWorkerAnalysisPdfBlob({
        sourceData,
        rangeLabel: range.label,
        stationFilter: profile.stationFilter,
        workerFilter: profile.workerFilter,
        orderLabel: profile.orderFilter.trim() || "Összes rendelés",
        productTypeFilter: profile.productTypeFilter,
        reportTitle: "Dolgozói időszaki elemzés",
        profileName: profile.name.trim(),
      });
    }
    return await createGenericReportDeliveryPdfBlob(profile, sourceData, range);
  }

  async function sendReportDeliveryProfile(profile: ReportDeliveryProfile, testOnly = false): Promise<void> {
    if (!supabase) throw new Error("Nincs Supabase kapcsolat.");
    if (!profile.id) throw new Error("A riportprofilt előbb létre kell hozni.");
    if (!profile.recipients.length) throw new Error("A riportprofilhoz nincs címzett.");

    const attemptedAt = new Date().toISOString();
    setReportDeliverySendingById((current) => ({ ...current, [profile.id]: true }));

    const readSendReportError = async (response: Response): Promise<string> => {
      const contentType = response.headers.get("content-type") || "";
      if (response.status === 404) {
        return "A /api/send-report végpont nem található. Tedd az app/api/send-report/route.ts fájlt a projektbe és deployold újra.";
      }
      if (contentType.includes("application/json")) {
        const data = await response.json().catch(() => null) as { error?: unknown; message?: unknown } | null;
        const message = String(data?.error || data?.message || "").trim();
        if (message) return message;
      }
      const raw = await response.text().catch(() => "");
      const clean = raw
        .replace(/<script[\s\S]*?<\/script>/gi, " ")
        .replace(/<style[\s\S]*?<\/style>/gi, " ")
        .replace(/<[^>]+>/g, " ")
        .replace(/&quot;/g, '"')
        .replace(/&amp;/g, "&")
        .replace(/\s+/g, " ")
        .trim();
      return clean.slice(0, 500) || response.statusText || `HTTP ${response.status}`;
    };

    let errors: string[] = [];
    try {
      const pdfBlob = await createReportDeliveryProfilePdfBlob(profile);

      for (const recipient of profile.recipients) {
        const formData = new FormData();
        formData.append("to", recipient);
        formData.append("subject", `${testOnly ? "[TESZT] " : ""}${profile.name}`);
        formData.append("html", `<p><strong>${profile.name}</strong></p><p>A csatolt PDF automatikusan generált termelési riport.</p>`);
        formData.append("text", `${profile.name}\nAutomatikusan generált termelési riport.`);
        formData.append("requestedFormat", "pdf");
        formData.append("pdf", pdfBlob, `${profile.name.replace(/[^a-zA-Z0-9_-]+/g, "_") || "riport"}.pdf`);

        try {
          const response = await fetch("/api/send-report", { method: "POST", body: formData });
          if (!response.ok) {
            errors.push(`${recipient}: ${await readSendReportError(response)}`);
          }
        } catch (error) {
          errors.push(`${recipient}: ${normalizeError(error)}`);
        }
      }

      const completedAt = new Date().toISOString();
      const status = errors.length ? "error" : "success";
      await writeReportDeliverySendLog(profile, {
        status: testOnly ? `test-${status}` : status,
        isTest: testOnly,
        errorMessage: errors.join(" | "),
        attemptedAt,
        completedAt,
      });

      if (testOnly) {
        void loadReportDeliverySendLogs(profile.id);
        if (errors.length) throw new Error(errors.join(" | "));
        setMessage({ type: "success", text: `Tesztküldés sikeres: ${profile.recipients.join(", ")}` });
        return;
      }

      const marker = getReportDeliveryScheduleMarker(profile);
      const lastSendError = errors.join(" | ");
      const updatePayload: Record<string, unknown> = errors.length
        ? {
            last_sent_marker: marker,
            last_attempt_at: completedAt,
            last_send_status: "error",
            last_send_error: lastSendError,
            updated_at: completedAt,
          }
        : {
            last_sent_marker: marker,
            last_sent_at: completedAt,
            last_attempt_at: completedAt,
            last_send_status: "success",
            last_send_error: "",
            updated_at: completedAt,
          };

      let response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).update(updatePayload).eq("id", profile.id);
      if (response.error && /last_attempt_at|last_send_status/i.test(String(response.error.message || ""))) {
        const legacyPayload = errors.length
          ? { last_sent_marker: marker, last_send_error: lastSendError, updated_at: completedAt }
          : { last_sent_marker: marker, last_sent_at: completedAt, last_send_error: "", updated_at: completedAt };
        response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).update(legacyPayload).eq("id", profile.id);
      }
      if (response.error) console.error("Riportküldési státusz mentési hiba:", response.error);

      const statusPatch: Partial<ReportDeliveryProfile> = {
        lastSentMarker: marker,
        lastSentAt: errors.length ? profile.lastSentAt : completedAt,
        lastAttemptAt: completedAt,
        lastSendStatus: errors.length ? "error" : "success",
        lastSendError,
      };
      setReportDeliveryProfiles((current) => current.map((item) => item.id === profile.id ? { ...item, ...statusPatch } : item));
      setReportDeliveryDrafts((current) => current[profile.id]
        ? { ...current, [profile.id]: { ...current[profile.id], ...statusPatch } }
        : current
      );
      void loadReportDeliverySendLogs(profile.id);

      if (errors.length) throw new Error(errors.join(" | "));
    } catch (error) {
      if (!testOnly && !errors.length) {
        const completedAt = new Date().toISOString();
        const errorText = normalizeError(error);
        errors = [errorText];
        await writeReportDeliverySendLog(profile, {
          status: "error",
          isTest: false,
          errorMessage: errorText,
          attemptedAt,
          completedAt,
        });
        const marker = getReportDeliveryScheduleMarker(profile);
        const updatePayload = {
          last_sent_marker: marker,
          last_attempt_at: completedAt,
          last_send_status: "error",
          last_send_error: errorText,
          updated_at: completedAt,
        };
        let response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).update(updatePayload).eq("id", profile.id);
        if (response.error && /last_attempt_at|last_send_status/i.test(String(response.error.message || ""))) {
          response = await supabase.from(REPORT_DELIVERY_PROFILES_TABLE).update({
            last_sent_marker: marker,
            last_send_error: errorText,
            updated_at: completedAt,
          }).eq("id", profile.id);
        }
        if (response.error) console.error("Riportküldési hibaállapot mentési hiba:", response.error);
        const statusPatch: Partial<ReportDeliveryProfile> = {
          lastSentMarker: marker,
          lastAttemptAt: completedAt,
          lastSendStatus: "error",
          lastSendError: errorText,
        };
        setReportDeliveryProfiles((current) => current.map((item) => item.id === profile.id ? { ...item, ...statusPatch } : item));
        setReportDeliveryDrafts((current) => current[profile.id]
          ? { ...current, [profile.id]: { ...current[profile.id], ...statusPatch } }
          : current
        );
        void loadReportDeliverySendLogs(profile.id);
      } else if (testOnly && !errors.length) {
        const completedAt = new Date().toISOString();
        const errorText = normalizeError(error);
        await writeReportDeliverySendLog(profile, {
          status: "test-error",
          isTest: true,
          errorMessage: errorText,
          attemptedAt,
          completedAt,
        });
        void loadReportDeliverySendLogs(profile.id);
      }
      throw error;
    } finally {
      setReportDeliverySendingById((current) => ({ ...current, [profile.id]: false }));
    }
  }

  async function checkAutomaticReportDeliveryProfiles(): Promise<void> {
    if (!supabase || reportDeliveryAutoCheckBusyRef.current) return;
    reportDeliveryAutoCheckBusyRef.current = true;
    try {
      // Mindig közvetlenül a Supabase-ból kérjük le az AKTÍV profilokat.
      // Így egy korábban "beragadt" profil sem tud elbújni egy kliensoldali régi állapot mögött.
      const response = await supabase
        .from(REPORT_DELIVERY_PROFILES_TABLE)
        .select("*")
        .eq("active", true)
        .order("created_at", { ascending: true });
      if (response.error) throw response.error;
      const activeFromDb = sortReportDeliveryProfiles(((response.data || []) as Record<string, unknown>[]).map(mapReportDeliveryProfileRow));
      const activeIds = new Set(activeFromDb.map((profile) => profile.id));

      setReportDeliveryProfiles((current) => current.map((profile) => {
        const fresh = activeFromDb.find((item) => item.id === profile.id);
        if (fresh) return { ...profile, ...fresh, recipients: [...fresh.recipients], customBlocks: [...fresh.customBlocks] };
        return profile.active ? { ...profile, active: false } : profile;
      }));
      setReportDeliveryDrafts((current) => {
        const next = { ...current };
        Object.keys(next).forEach((id) => {
          if (!activeIds.has(id) && next[id].active) next[id] = { ...next[id], active: false };
          const fresh = activeFromDb.find((item) => item.id === id);
          if (fresh) {
            // Az űrlapban megadott, még nem mentett szűréseket nem írjuk felül;
            // csak a futási státuszt frissítjük a DB-ből.
            next[id] = {
              ...next[id],
              active: true,
              lastSentMarker: fresh.lastSentMarker,
              lastSentAt: fresh.lastSentAt,
              lastAttemptAt: fresh.lastAttemptAt,
              lastSendStatus: fresh.lastSendStatus,
              lastSendError: fresh.lastSendError,
            };
          }
        });
        return next;
      });

      const now = new Date();
      for (const profile of activeFromDb) {
        if (!isReportDeliveryProfileDue(profile, now)) continue;
        try {
          await sendReportDeliveryProfile(profile, false);
        } catch (error) {
          console.error(`Automatikus riportküldés sikertelen (${profile.name}):`, error);
        }
      }
    } finally {
      reportDeliveryAutoCheckBusyRef.current = false;
    }
  }

