  async function loadIncompleteBatches(worker: Worker | null = activeWorker): Promise<void> {
    if (!supabase || !worker) {
      setMessage({ type: "error", text: "Nincs kiválasztott dolgozó a félbemaradt kötegek betöltéséhez." });
      return;
    }

    setBusy(true);
    try {
      const munkakor = (worker.Munkakor || "").trim();
      const query = supabase
        .from("incomplete_batches")
        .select("id, megnevezes, vonalkod, munkakor, created_at")
        .order("created_at", { ascending: false });
      const { data, error } = munkakor ? await query.eq("munkakor", munkakor) : await query;
      if (error) throw error;
      setIncompleteBatches(Array.isArray(data) ? data : []);
      setShowIncompleteBatches(true);
      setMessage({
        type: "info",
        text: Array.isArray(data) && data.length > 0
          ? `Betöltve ${data.length} félbemaradt köteg a(z) ${munkakor || "ismeretlen"} munkakörhöz.`
          : "Nincs félbemaradt köteg ehhez a munkakörhöz.",
      });
    } catch (error) {
      console.error("SUPABASE HIBA loadIncompleteBatches:", error);
      setMessage({ type: "error", text: normalizeError(error) });
    } finally {
      setBusy(false);
    }
  }

