  function handleEventSelection(event: EventCard): void {
    setSelectedEventCard(event);
    setEventConfirmationCode(event.barcodeValue);
    setEventConfirmationInput("");
    setMessage({
      type: "info",
      text: `${event.label} kijelölve. A továbblépéshez csippantsd le a kártyán látható esemény-visszaigazoló vonalkódot.`,
    });
  }

  async function handleEventBarcodeSubmit(scannedValue?: string): Promise<void> {
    if (eventBarcodeProcessingRef.current || eventBarcodeSubmitLockRef.current) return;
    eventBarcodeProcessingRef.current = true;
    eventBarcodeSubmitLockRef.current = true;
    if (eventBarcodeAutoSubmitTimerRef.current) {
      clearTimeout(eventBarcodeAutoSubmitTimerRef.current);
      eventBarcodeAutoSubmitTimerRef.current = null;
    }

    try {
      const candidate = (scannedValue ?? eventBarcodeLatestValueRef.current ?? eventConfirmationInput).trim();
      if (!candidate) {
        setEventScanError("Csippantsd le vagy írd be az esemény vonalkódját.");
        setMessage({ type: "error", text: "Csippantsd le vagy írd be az esemény vonalkódját." });
        eventBarcodeLatestValueRef.current = "";
        setEventConfirmationInput("");
        window.setTimeout(() => focusAndSelectInput(eventBarcodeInputRef), 0);
        return;
      }

      const matchedEvent = filteredEvents.find(
        (event) => (event.barcodeValue || "").trim().toLowerCase() === candidate.toLowerCase()
      );

      if (!matchedEvent) {
        eventBarcodeLatestValueRef.current = "";
        setEventConfirmationInput("");
        setEventScanError(`Ismeretlen esemény vonalkód: ${candidate}`);
        setMessage({ type: "error", text: `Ismeretlen esemény vonalkód: ${candidate}` });
        window.setTimeout(() => focusAndSelectInput(eventBarcodeInputRef), 0);
        return;
      }

      setSelectedEventCard(matchedEvent);
      setSelectedEvent(null);
      setEventConfirmationCode(matchedEvent.barcodeValue);
      eventBarcodeLatestValueRef.current = "";
      setEventConfirmationInput("");
      setEventScanError("");
      setPendingAction(null);
      setOrderNumber("");
      setActionBarcode("");
      setEndBarcodeConfirmed(false);
      setScrapQty("");
    setOuterSheetScrap(false);
    setInnerSheetScrap(false);
    setToklecScrap(false);
    setTokKesz(false);
    setNyiloKesz(false);
    setTokKeszLocked(false);
    setNyiloKeszLocked(false);
    setPanelAjtolapokKesz(false);
    setPanelToklecKesz(false);
    setPanelAjtolapokLocked(false);
    setPanelToklecLocked(false);
    setThreePartKulsoKesz(false);
    setThreePartBelsoKesz(false);
    setThreePartToklecKesz(false);
    setThreePartKulsoLocked(false);
    setThreePartBelsoLocked(false);
    setThreePartToklecLocked(false);
      setEndNote("");
      setEndDarab("");
      setEndSzal("");
      orderTypeLatestValueRef.current = "";
      setOrderTypeInput("");
      setOrderTypeScanError("");
      setManagementSelection(null);
      setTerminalView("scanner");

      if (workerEventKoteg === 6 || workerEventKoteg === 7 || workerEventKoteg === 8) {
        setWorkflowMode("single");
        setPendingAction("START");
        setBatchCode("");
        setBatchOrders([]);
        setBatchOrderProductionMeta({});
        setFlowStage("order-scan");
        setStep(5);
        setMessage({
          type: "success",
          text: workerEventKoteg === 8
            ? `${matchedEvent.label} esemény beolvasva. 8-as gyorsjelentés aktív; olvasd be a rendelésszámot, és azonnal Kész lesz.`
            : workerEventKoteg === 7
              ? `${matchedEvent.label} esemény beolvasva. 7-es Külső lap + Belső lap + Tokléc mód aktív; olvasd be a rendelésszámot.`
              : `${matchedEvent.label} esemény beolvasva. 6-os egyedi Ajtólapok + Tokléc mód aktív; olvasd be a rendelésszámot.`,
        });
        window.setTimeout(() => focusAndSelectInput(orderInputRef, { preventScroll: true }), 0);
        return;
      }

      if (workerEventKoteg === 5) {
        setWorkflowMode(null);
        setPendingAction("START");
        setBatchCode("");
        setBatchOrders([]);
        setBatchOrderProductionMeta({});
        setOrderTypeInput("");
        orderTypeLatestValueRef.current = "";
        setFlowStage("batch-selection");
        setStep(4);
        setMessage({ type: "success", text: `${matchedEvent.label} esemény beolvasva. Válaszd ki az Egyedi rendelés vagy Köteg létrehozása módot.` });
        window.setTimeout(() => focusAndSelectInput(orderTypeInputRef, { preventScroll: true }), 0);
        return;
      }

      if (workerEventKoteg === 4) {
        setWorkflowMode("single");
        setPendingAction("START");
        setBatchCode("");
        setBatchOrders([]);
        setBatchOrderProductionMeta({});
        setFlowStage("order-scan");
        setStep(5);
        setMessage({ type: "success", text: `${matchedEvent.label} esemény beolvasva. Fóliázó / lap-selejt mód aktív; olvasd be a rendelésszámot.` });
        return;
      }

      setWorkflowMode("single");
      setPendingAction("START");
      setBatchOrders([]);
      setBatchOrderProductionMeta({});
      setFlowStage("order-scan");
      setStep(5);
      setMessage({ type: "success", text: `${matchedEvent.label} esemény beolvasva. Olvasd be a rendelésszámot; START nélkül azonnal mentésre kerül.` });
      window.setTimeout(() => focusAndSelectInput(orderInputRef), 0);
    } finally {
      window.setTimeout(() => {
        eventBarcodeProcessingRef.current = false;
        eventBarcodeSubmitLockRef.current = false;
      }, 320);
    }
  }

  function handleBackFromManagementView(): void {
    setTerminalView("scanner");
    setManagementSelection(null);
    setEventConfirmationInput("");
    eventBarcodeLatestValueRef.current = "";
    setEventScanError("");
    window.setTimeout(() => {
      focusAndSelectInput(eventBarcodeInputRef);
    }, 0);
  }

  function confirmSelectedEvent(): void {
    void handleEventBarcodeSubmit();
  }

  function startSingleWorkflow(): void {
    handleOrderTypeSelection("single");
  }

  function normalizeProductionBatchOrders(value: unknown): string[] {
    if (Array.isArray(value)) {
      return value.map((item) => String(item ?? "").trim()).filter(Boolean);
    }
    if (typeof value === "string") {
      try {
        const parsed = JSON.parse(value);
        if (Array.isArray(parsed)) return parsed.map((item) => String(item ?? "").trim()).filter(Boolean);
      } catch {
        return value.split(/[;,\n]+/).map((item) => item.trim()).filter(Boolean);
      }
    }
    return [];
  }

  function hydrateProductionBatch(row: any): ProductionBatchRow {
    return {
      id: row?.id,
      batch_code: String(row?.batch_code || ""),
      created_at: String(row?.created_at || new Date().toISOString()),
      start_time: row?.start_time ? String(row.start_time) : null,
      machine_id: row?.machine_id ? String(row.machine_id) : null,
      order_ids: normalizeProductionBatchOrders(row?.order_ids),
      worker_name: row?.worker_name ? String(row.worker_name) : null,
      production_meta: normalizeProductionMetaMap(row?.production_meta),
      operation_code: normalizeBatchOperationCode(row?.operation_code),
      operation_status: normalizeBatchOperationStatus(row?.operation_status),
    };
  }
  function isFoilSheetScrapWorker(worker: Worker | null = activeWorker): boolean {
    const mode = Number(getWorkerEsemenyKotegValue(worker));
    return !!worker && (mode === 4 || mode === 5 || mode === 6 || mode === 7);
  }

  function isEventFiveBatchWorker(worker: Worker | null = activeWorker): boolean {
    return !!worker && Number(getWorkerEsemenyKotegValue(worker)) === 5;
  }

  function isEventSixBatchWorker(worker: Worker | null = activeWorker): boolean {
    // A 6-os mód mostantól kizárólag egyedi rendelés.
    // A régi batch feldolgozó kód kompatibilitásként bent marad, de új 6-os
    // folyamatból nem érhető el.
    return false;
  }

  function isPanelTwoPartWorker(worker: Worker | null = activeWorker): boolean {
    return !!worker && Number(getWorkerEsemenyKotegValue(worker)) === 6;
  }

  function isThreePartWorker(worker: Worker | null = activeWorker): boolean {
    return !!worker && Number(getWorkerEsemenyKotegValue(worker)) === 7;
  }

  function isInstantWarehouseWorker(worker: Worker | null = activeWorker): boolean {
    return !!worker && Number(getWorkerEsemenyKotegValue(worker)) === 8;
  }

  function isDoorTwoPartWorker(worker: Worker | null = activeWorker): boolean {
    return !!worker && Number(getWorkerEsemenyKotegValue(worker)) === 5;
  }

  async function fetchDoorCompletionStateForOrder(
    orderNumber: string,
    machineName = getCurrentMachineIdForInsert()
  ): Promise<DoorCompletionSnapshot> {
    if (!supabase) return { ...EMPTY_DOOR_COMPLETION_SNAPSHOT };
    const cleanOrderNumber = String(orderNumber || "").trim();
    const cleanMachineName = String(machineName || "").trim();
    if (!cleanOrderNumber || !cleanMachineName) return { ...EMPTY_DOOR_COMPLETION_SNAPSHOT };

    const { data, error } = await supabase
      .from("work_logs")
      .select("worker_id, worker_name, order_number, action, created_at, start_timestamp, end_timestamp, start_time, end_time, machine_id, ujragyartas, ujragyartas_sorszam, tok_kesz, nyilo_kesz, reszleges_keszultseg, tok_kesz_worker_name, tok_kesz_at, nyilo_kesz_worker_name, nyilo_kesz_at")
      .eq("order_number", cleanOrderNumber)
      .eq("machine_id", cleanMachineName)
      .order("created_at", { ascending: true })
      .limit(1000);
    if (error) throw error;
    return resolveDoorCompletionSnapshot((data || []) as WorkLogRow[]);
  }


